/* Spanish translation of the ISC2 SSCP practice questions. Options keep the same order as the English bank. */
CertHub.addQuestionsEs("sscp", {
  "ss1": ["En una situación que enfrentas, dos cánones del Código de Ética de ISC2 parecen entrar en conflicto. ¿Qué canon tiene prioridad?", ["Brindar un servicio diligente y competente a los mandantes", "Promover y proteger la profesión", "Proteger a la sociedad, el bien común, la confianza pública necesaria y la infraestructura", "Actuar de manera honorable, honesta, justa, responsable y legal"], "Los cánones se aplican en orden, y proteger a la sociedad y la infraestructura va primero.", ["Servir a los mandantes es el tercer canon, así que cede ante el deber de proteger a la sociedad cuando ambos entran en conflicto.", "Promover la profesión es el cuarto canon y el de menor prioridad, así que nunca prevalece sobre los demás.", null, "Actuar de manera honorable y legal es el segundo canon; es importante, pero sigue estando por debajo de proteger a la sociedad."]],
  "ss2": ["Un técnico de mesa de ayuda cuya única tarea es restablecer contraseñas de usuarios tiene derechos de Domain Admin. ¿Cuál es la MEJOR acción?", ["Otorgar solo el permiso delegado para restablecer contraseñas y quitar la membresía de Domain Admin", "Mantener los derechos de Domain Admin pero habilitar una auditoría detallada de la cuenta", "Hacer que el técnico firme una política de uso aceptable", "Rotar la contraseña de Domain Admin cada mes"], "El mínimo privilegio significa otorgar solo el acceso que el trabajo necesita; la auditoría y las políticas no eliminan el privilegio excesivo.", [null, "La auditoría solo registra lo que hace la cuenta con privilegios excesivos; deja en su lugar los derechos de Domain Admin sobrantes.", "Una política de uso aceptable es un control directivo que establece expectativas, pero no elimina los privilegios innecesarios.", "Rotar la contraseña protege la credencial, pero el técnico sigue teniendo muchos más derechos de los que requiere su trabajo."]],
  "ss3": ["¿Qué control evita MEJOR que un solo empleado pueda crear un proveedor nuevo y además aprobar pagos a ese proveedor?", ["Rotación de puestos", "Vacaciones obligatorias", "Necesidad de saber (need to know)", "Separación de funciones"], "La separación de funciones divide un proceso sensible para que una sola persona no pueda completarlo; los demás controles ayudan principalmente a detectar el fraude después de ocurrido.", ["La rotación de puestos mueve a las personas entre roles para que el fraude pueda descubrirse más adelante; no impide que una persona complete ambos pasos.", "Las vacaciones obligatorias son un control detectivo que expone un fraude en curso mientras la persona está ausente, no una división preventiva de funciones.", "La necesidad de saber limita el acceso a la información según la necesidad, pero no exige que dos personas distintas intervengan en una transacción sensible.", null]],
  "ss4": ["Un controlador heredado no admite MFA, así que se coloca en una VLAN aislada a la que solo se puede llegar a través de un jump host monitoreado. ¿Qué tipo de control es este?", ["Disuasivo", "Compensatorio", "Directivo", "Correctivo"], "Un control compensatorio es una salvaguarda alternativa que se usa cuando no puede implementarse el control principal.", ["Un control disuasivo desalienta a los atacantes, como los carteles de advertencia; aquí el aislamiento en realidad reemplaza un control faltante.", null, "Un control directivo indica a las personas qué hacer, como una política o un procedimiento, en lugar de restringir técnicamente el acceso.", "Un control correctivo repara el daño después de un incidente, como restaurar desde un respaldo, que no es lo que hace la VLAN."]],
  "ss5": ["¿Qué afirmación describe MEJOR la defensa en profundidad?", ["Desplegar el firewall más fuerte disponible en el perímetro de la red", "Superponer múltiples controles independientes para que la falla de uno no exponga el activo", "Concentrar el gasto en seguridad en el activo más valioso", "Cifrar todos los datos para que los demás controles sean innecesarios"], "La defensa en profundidad se basa en varias capas superpuestas en lugar de un único control fuerte.", ["Un único firewall perimetral fuerte es una sola capa; si falla o es evadido, nada más protege el activo.", null, "Concentrar el gasto en un activo es una decisión de priorización, no la superposición de múltiples controles independientes.", "El cifrado es un control; depender solo de él es lo opuesto a la defensa en profundidad."]],
  "ss6": ["Un atacante altera los montos de la nómina mientras el archivo está en tránsito hacia el banco. ¿Qué principio de seguridad se violó?", ["Confidencialidad", "Disponibilidad", "Privacidad", "Integridad"], "La modificación no autorizada de datos es una pérdida de integridad.", ["La confidencialidad trata sobre la divulgación no autorizada; aquí los datos se cambiaron, no solo se leyeron.", "La disponibilidad se refiere al acceso oportuno a los datos y sistemas, que no se perdió en este escenario.", "La privacidad se refiere al manejo de los datos personales de las personas, mientras que el ataque aquí fue una modificación no autorizada.", null]],
  "ss7": ["¿Por qué deben probarse y revisarse periódicamente los controles de seguridad implementados?", ["Para confirmar que siguen funcionando como se espera a medida que cambian los sistemas, las amenazas y las necesidades del negocio", "Porque los auditores exigen que cada control se reemplace cada año", "Para reducir la cantidad de controles que deben documentarse", "Para trasladar la responsabilidad de los controles de la dirección a TI"], "Los controles se desvían y los entornos cambian, así que la verificación continua demuestra que siguen siendo efectivos.", [null, "Los auditores esperan que los controles se prueben para verificar su efectividad, no que se reemplacen cada año.", "Probar los controles no reduce la documentación; los resultados normalmente se suman a la evidencia documentada.", "La dirección sigue siendo responsable de los controles; las revisiones verifican su efectividad en lugar de trasladar la responsabilidad."]],
  "ss8": ["¿Cuál es el requisito previo MÁS importante para aplicar la protección adecuada a los activos de información?", ["Un contrato firmado con un proveedor de seguridad gestionada", "Cifrado de disco completo en cada endpoint", "Un inventario preciso con un responsable y una clasificación asignados a cada activo", "Una prueba de penetración de la red completada"], "No puedes proteger lo que no sabes que tienes; la propiedad y la clasificación determinan qué controles se aplican.", ["Un proveedor de seguridad gestionada puede ayudar a operar controles, pero no puede proteger activos que no fueron identificados y clasificados.", "El cifrado de disco completo es un control; decidir dónde y con qué fuerza proteger los datos requiere primero conocer los activos y su valor.", null, "Una prueba de penetración encuentra debilidades explotables, pero supone que ya sabes qué activos están en el alcance y cuánto valen."]],
  "ss9": ["¿Quién es el responsable final de decidir el nivel de clasificación de una base de datos de clientes?", ["El custodio de los datos", "El administrador de la base de datos", "El administrador de seguridad", "El propietario de los datos"], "El propietario de los datos, un rol del negocio, es quien rinde cuentas por la clasificación; los custodios implementan los controles resultantes.", ["El custodio implementa y mantiene las protecciones, como los respaldos; no decide el nivel de clasificación.", "El DBA es un rol técnico de custodio que aplica controles, no el rol del negocio que rinde cuentas por clasificar los datos.", "El administrador de seguridad configura los controles según la clasificación, pero no la establece.", null]],
  "ss10": ["Se van a retirar unidades de estado sólido que contienen datos confidenciales y saldrán de la organización. ¿Qué método es el MÁS apropiado?", ["Desmagnetizar (degauss) las unidades", "Destrucción física, como la trituración", "Realizar un formateo rápido", "Eliminar todas las particiones"], "La desmagnetización no funciona en almacenamiento flash y el formateo deja datos recuperables; la destrucción garantiza que los datos no puedan recuperarse.", ["La desmagnetización se basa en campos magnéticos y no borra la memoria flash, así que los datos de los SSD pueden quedar.", null, "Un formateo rápido solo reescribe las estructuras del sistema de archivos y deja los datos subyacentes fácilmente recuperables.", "Eliminar las particiones borra las entradas de la tabla de particiones, pero deja los bloques de datos intactos y recuperables."]],
  "ss11": ["Un técnico quiere aplicar un cambio urgente de una regla del firewall en producción durante el horario laboral. ¿Qué debe hacer PRIMERO el técnico?", ["Aplicar el cambio ahora y documentarlo después", "Aplicar el cambio y monitorear si hay quejas", "Enviarlo a través del proceso de gestión de cambios, usando el procedimiento de cambio de emergencia si se justifica", "Pedir al fabricante del firewall que apruebe la regla"], "Incluso los cambios urgentes necesitan revisión y aprobación, con procedimientos de emergencia que igualmente registran el impacto y los pasos de reversión.", ["Hacer el cambio primero evita la revisión y la aprobación, que es justamente lo que la gestión de cambios busca impedir.", "Monitorear las quejas no sustituye el análisis de impacto, la aprobación ni un plan de reversión.", null, "El fabricante no tiene autoridad sobre los cambios de tu organización; la aprobación debe venir de tu propio proceso de cambios."]],
  "ss12": ["¿Qué métrica muestra MEJOR que la capacitación de concientización sobre phishing está cambiando el comportamiento?", ["Tasas de clics en descenso y tasas de reporte en aumento a lo largo de simulaciones de phishing repetidas", "El porcentaje del personal que completó el módulo de capacitación", "La cantidad de sesiones de capacitación dictadas este año", "Los puntajes promedio del cuestionario final del curso"], "La finalización y los puntajes de los cuestionarios miden la asistencia y el recuerdo, no si las personas actúan de manera diferente.", [null, "El porcentaje de finalización muestra quién terminó el módulo, no si ahora detecta y reporta el phishing.", "Contar las sesiones dictadas mide el esfuerzo de capacitación, no un cambio en el comportamiento del personal.", "Los puntajes del cuestionario miden el recuerdo a corto plazo del material, no el comportamiento real cuando llega un correo de phishing."]],
  "ss13": ["Los empleados sostienen la puerta abierta para las personas que los siguen hacia un área segura. ¿Qué control resuelve MEJOR esto?", ["Un vestíbulo de control de acceso (mantrap) que admite a una persona por autenticación", "Más cámaras CCTV en la entrada", "Un cartel de advertencia sobre el tailgating", "Un registro de visitantes en la recepción"], "Un vestíbulo impide físicamente el tailgating; las cámaras y los carteles solo lo detectan o lo desalientan.", [null, "El CCTV es un control detectivo que registra el tailgating, pero no lo detiene físicamente.", "Un cartel de advertencia es un disuasivo que las personas pueden ignorar; no obliga a que entre una persona por vez.", "Un registro de visitantes anota a quién se admitió, pero no impide que los empleados dejen que otros los sigan."]],
  "ss14": ["¿Qué combinación ofrece una verdadera autenticación multifactor?", ["Una contraseña y la respuesta a una pregunta de seguridad", "Un escaneo de huella dactilar y un escaneo de la palma", "Una contraseña y un código de un solo uso de un token de hardware", "Un PIN y una frase de contraseña"], "MFA requiere tipos de factores distintos; las otras opciones usan dos elementos del mismo factor.", ["Una contraseña y la respuesta a una pregunta de seguridad son ambas algo que sabes, así que es autenticación de un solo factor.", "Los escaneos de huella y de palma son ambos biométricos (algo que eres), así que se usa un solo tipo de factor.", null, "Un PIN y una frase de contraseña son ambos factores de conocimiento, así que combinarlos no constituye MFA."]],
  "ss15": ["En un sistema biométrico que protege un centro de datos, ¿qué tasa de error debe minimizarse PRIMERO?", ["Tasa de falso rechazo", "Tasa de falsa aceptación", "Tasa de fallo de registro (failure-to-enroll)", "Tasa de procesamiento (throughput)"], "Las falsas aceptaciones dejan entrar a personas no autorizadas, lo que es el mayor riesgo en un área de alta seguridad.", ["Los falsos rechazos incomodan a los usuarios legítimos, pero no dejan entrar a personas no autorizadas al centro de datos.", null, "El fallo de registro afecta cuántos usuarios pueden inscribirse en el sistema, no si se admite a impostores.", "La tasa de procesamiento mide qué tan rápido se atiende a las personas, una métrica de usabilidad y no una tasa de error de seguridad."]],
  "ss16": ["¿Cuál es el MAYOR riesgo de seguridad que introduce el inicio de sesión único?", ["Los usuarios deben recordar más contraseñas", "Aumenta el tráfico de autenticación en la red", "Aumentan las llamadas a la mesa de ayuda para restablecer contraseñas", "El compromiso de una sola credencial puede dar acceso a muchos sistemas"], "SSO concentra el acceso detrás de una sola credencial, así que protegerla con MFA se vuelve crítico.", ["SSO reduce la cantidad de contraseñas que los usuarios deben recordar; ese es uno de sus beneficios.", "SSO normalmente reduce el tráfico de autenticación repetida, y la carga de la red no es su principal riesgo de seguridad.", "SSO normalmente reduce las llamadas para restablecer contraseñas porque los usuarios manejan menos credenciales.", null]],
  "ss17": ["¿Qué estándar intercambia aserciones de autenticación y autorización basadas en XML entre un proveedor de identidad y un proveedor de servicios para SSO en el navegador?", ["LDAP", "RADIUS", "SAML", "Kerberos"], "SAML define las aserciones que se transmiten entre un IdP y un SP en el SSO web federado.", ["LDAP es un protocolo de acceso a directorios que se usa para consultar y autenticarse contra un directorio, no para transmitir aserciones XML federadas.", "RADIUS ofrece AAA para el acceso a la red, como VPN y Wi-Fi, no SSO federado basado en el navegador.", null, "Kerberos usa tickets dentro de un realm o dominio y no es un formato de aserciones XML para SSO web entre organizaciones."]],
  "ss18": ["Una aplicación web necesita verificar la identidad de un usuario usando su cuenta de red social existente. ¿Qué protocolo agrega una capa de autenticación sobre OAuth 2.0 con este fin?", ["OpenID Connect", "OAuth 2.0 por sí solo", "TACACS+", "NTLM"], "OAuth 2.0 maneja la autorización delegada; OpenID Connect agrega tokens de ID para autenticar al usuario.", [null, "OAuth 2.0 por sí solo solo delega la autorización a recursos; no define una forma estándar de autenticar al usuario.", "TACACS+ es un protocolo AAA para administrar dispositivos de red, no para iniciar sesión en la web con cuentas de redes sociales.", "NTLM es un protocolo heredado de desafío-respuesta de Windows y no tiene relación con los inicios de sesión sociales basados en OAuth."]],
  "ss19": ["El dominio A confía en el dominio B, y el dominio B confía en el dominio C, y todas las confianzas son transitivas. ¿Cuál es la PRINCIPAL preocupación de seguridad para el dominio A?", ["Los usuarios del dominio A pierden el acceso al dominio B", "Ya no pueden emitirse tickets de Kerberos en el dominio A", "Los administradores del dominio C deben restablecer las contraseñas del dominio A", "Los usuarios del dominio C podrían llegar a recursos del dominio A sin que el dominio A haya aprobado una confianza con C"], "La confianza transitiva extiende el acceso de forma implícita, así que las organizaciones deben revisar y limitar las relaciones de confianza.", ["Las relaciones de confianza extienden el acceso; no quitan el acceso de los usuarios del dominio A al dominio B.", "Establecer confianzas no impide que los controladores del propio dominio A emitan tickets de Kerberos.", "Las confianzas no obligan a los administradores del dominio C a restablecer contraseñas en el dominio A.", null]],
  "ss20": ["Un empleado pasa de cuentas por pagar a marketing. ¿Cuál es la acción de gestión de identidades MÁS importante?", ["Agregar los permisos de marketing a la cuenta existente", "Quitar el acceso de cuentas por pagar que ya no necesita mientras se aprovisiona el rol de marketing", "Crear una segunda cuenta para el rol de marketing", "Esperar a la próxima revisión trimestral de accesos para ajustar los permisos"], "Quitar el acceso anterior al cambiar de puesto evita la acumulación de privilegios (privilege creep) y preserva la separación de funciones.", ["Agregar permisos nuevos sin quitar los anteriores es exactamente como ocurre la acumulación de privilegios.", null, "Una segunda cuenta duplica la superficie de ataque y sigue dejando el acceso anterior en su lugar.", "Esperar a la próxima revisión deja activo durante meses un acceso innecesario a los pagos."]],
  "ss21": ["Un administrador de sistemas va a ser despedido de forma involuntaria. ¿Cuándo debe deshabilitarse su acceso?", ["Al final del último día de trabajo del empleado", "En el momento en que se notifica al empleado, o justo antes", "Después de que el empleado devuelva el equipo de la empresa", "Dentro de 30 días, según el SLA estándar de desaprovisionamiento"], "Deshabilitar el acceso al momento de la notificación elimina la posibilidad de que un usuario privilegiado descontento cause daños.", ["Esperar hasta el final del día le da a un administrador privilegiado, posiblemente descontento, horas para causar daño.", null, "La devolución del equipo es un paso aparte; el acceso no debe permanecer activo mientras se espera.", "Un plazo de 30 días es demasiado largo para el despido involuntario de un usuario privilegiado."]],
  "ss22": ["¿Cuál es el propósito PRINCIPAL de la recertificación periódica de accesos por parte de los gerentes?", ["Obligar a los usuarios a cambiar sus contraseñas", "Medir con qué frecuencia inician sesión los usuarios", "Transferir la propiedad de las cuentas al equipo de seguridad", "Detectar y eliminar permisos acumulados o inapropiados"], "La recertificación confirma que el acceso de cada usuario sigue siendo necesario y detecta la acumulación de privilegios.", ["Los cambios de contraseña se gestionan mediante la política de contraseñas, no mediante la recertificación de accesos por parte de los gerentes.", "La frecuencia de inicio de sesión es una métrica de actividad; la recertificación juzga si el acceso sigue siendo apropiado.", "La recertificación mantiene la propiedad en manos de los gerentes del negocio; no entrega las cuentas al equipo de seguridad.", null]],
  "ss23": ["¿En qué modelo de control de acceso el sistema impone el acceso usando etiquetas de sensibilidad y autorizaciones (clearances), sin que los usuarios puedan cambiar los permisos?", ["Control de acceso obligatorio (MAC)", "Control de acceso discrecional (DAC)", "Control de acceso basado en roles (RBAC)", "Control de acceso basado en reglas"], "MAC lo impone el sistema según las etiquetas; los propietarios no pueden otorgar acceso a su discreción.", [null, "En DAC el propietario decide quién obtiene acceso, así que los usuarios pueden cambiar los permisos de lo que les pertenece.", "RBAC otorga permisos según los roles de trabajo, no según etiquetas de sensibilidad y autorizaciones.", "El control basado en reglas aplica reglas globales como las ACL y no depende de etiquetas de clasificación ni de autorizaciones."]],
  "ss24": ["Un hospital con alta rotación de personal quiere que los permisos sigan las funciones del puesto, como enfermero, médico y empleado de facturación. ¿Qué modelo es el MÁS apropiado?", ["Control de acceso discrecional", "Control de acceso obligatorio", "Control de acceso basado en roles", "Listas de control de acceso mantenidas por usuario"], "RBAC asigna los permisos a roles, así que los usuarios obtienen el acceso correcto simplemente al ser ubicados en un rol.", ["DAC permite que cada propietario otorgue acceso, lo que se vuelve inconsistente y difícil de gestionar con alta rotación.", "MAC se basa en etiquetas y autorizaciones, lo cual es rígido y no está diseñado en torno a funciones como enfermero o empleado administrativo.", null, "Las ACL por usuario deben editarse en cada alta y baja, lo opuesto a lo que requiere una alta rotación."]],
  "ss25": ["El acceso a un informe debe permitirse solo al personal de finanzas que use un dispositivo administrado durante el horario laboral. ¿Qué modelo respalda MEJOR esta política?", ["Control de acceso basado en roles", "Control de acceso discrecional", "Control de acceso obligatorio", "Control de acceso basado en atributos (ABAC)"], "ABAC evalúa en una sola política atributos del usuario, del dispositivo y del entorno (como la hora).", ["RBAC puede verificar el rol de finanzas, pero no el estado del dispositivo ni la hora del día sin lógica de atributos adicional.", "DAC depende de que el propietario otorgue el acceso y no puede evaluar condiciones de dispositivo u horario.", "MAC compara etiquetas y autorizaciones y no puede expresar condiciones como dispositivo administrado y horario laboral.", null]],
  "ss26": ["Un servidor está valuado en $200,000. Una inundación causaría un 25% de daño y se espera una vez cada dos años. ¿Cuál es la expectativa de pérdida anualizada (ALE)?", ["$50,000", "$25,000", "$100,000", "$12,500"], "SLE = 200,000 x 0.25 = 50,000; ALE = SLE x ARO = 50,000 x 0.5 = 25,000.", ["$50,000 es la expectativa de pérdida única (SLE); todavía hay que multiplicarla por el ARO de 0.5.", null, "$100,000 requeriría aplicar un ARO de 2 a la SLE, pero la inundación se espera solo una vez cada dos años.", "$12,500 es la mitad del resultado correcto, como si la inundación ocurriera solo una vez cada cuatro años."]],
  "ss27": ["Una organización contrata un ciberseguro para cubrir las pérdidas por brechas de datos. ¿Qué tratamiento del riesgo es este?", ["Evitación del riesgo", "Mitigación del riesgo", "Transferencia del riesgo", "Aceptación del riesgo"], "El seguro traslada el impacto financiero a un tercero; no reduce la probabilidad de la brecha.", ["La evitación significa dejar por completo la actividad riesgosa, como no recopilar los datos.", "La mitigación reduce la probabilidad o el impacto mediante controles; el seguro no hace que una brecha sea menos probable.", null, "La aceptación significa asumir la pérdida sin tomar medidas, mientras que contratar un seguro traslada activamente el impacto financiero."]],
  "ss28": ["¿Quién debe aceptar formalmente el riesgo residual que queda después de aplicar controles a un sistema de negocio?", ["El responsable del negocio o el gerente sénior con autoridad sobre el sistema", "El profesional de seguridad que realizó la evaluación", "El auditor externo", "El administrador del sistema"], "La aceptación del riesgo es una decisión de la dirección que toma alguien que rinde cuentas por el impacto en el negocio.", [null, "El profesional evalúa y recomienda, pero no tiene la autoridad de negocio para aceptar el riesgo en nombre de la organización.", "Un auditor externo debe mantenerse independiente y solo evalúa los controles; aceptar el riesgo comprometería ese rol.", "El administrador del sistema opera el sistema como custodio y no rinde cuentas por el impacto del riesgo en el negocio."]],
  "ss29": ["¿Qué describe MEJOR el análisis de riesgo cualitativo?", ["Calificar la probabilidad y el impacto con categorías como alto, medio y bajo", "Calcular SLE, ARO y ALE en términos monetarios", "Usar escáneres automáticos para contar vulnerabilidades", "Basarse únicamente en tablas actuariales de seguros"], "El análisis cualitativo usa calificaciones relativas y juicio en lugar de valores monetarios.", [null, "Calcular SLE, ARO y ALE en dinero es análisis cuantitativo, el enfoque opuesto.", "Contar vulnerabilidades con escáneres es una actividad de evaluación y no dice nada sobre calificar la probabilidad y el impacto.", "Las tablas actuariales aportan probabilidades numéricas usadas en el análisis cuantitativo, no calificaciones relativas de alto/medio/bajo."]],
  "ss30": ["Antes de enviar logs que contienen datos personales de clientes a un proveedor de monitoreo en otro país, ¿qué debe hacer PRIMERO el analista?", ["Cifrar los logs y enviarlos", "Quitar las marcas de tiempo de los logs", "Confirmar con legal o cumplimiento los requisitos legales y de privacidad para la transferencia internacional", "Pedir al proveedor que firme un acuerdo de confidencialidad"], "Las leyes de privacidad y de residencia de datos pueden restringir la transferencia, así que hay que confirmar las obligaciones antes de actuar.", ["El cifrado protege los datos en tránsito, pero no vuelve legal una transferencia internacional que de otro modo sería ilegal.", "Quitar las marcas de tiempo destruye la utilidad de los logs y no hace nada respecto de los datos personales que contienen.", null, "Un NDA es un control contractual, pero hay que confirmar los requisitos legales de la transferencia antes de elegir los términos del contrato."]],
  "ss31": ["¿Qué escaneo de vulnerabilidades ofrece la visión MÁS precisa de los parches faltantes en los servidores?", ["Un escaneo externo sin autenticación", "Un escaneo autenticado (con credenciales)", "Un ping sweep", "Un escaneo pasivo del tráfico de red"], "Los escaneos con credenciales pueden leer directamente el software instalado y la configuración, lo que reduce las suposiciones y los falsos positivos.", ["Un escaneo sin autenticación solo puede inferir los niveles de parches a partir de banners y respuestas, lo que genera más suposiciones y falsos positivos.", null, "Un ping sweep solo descubre qué hosts están activos; no verifica el software instalado ni los parches.", "El análisis pasivo de tráfico solo ve lo que atraviesa la red y no puede inventariar de forma confiable los parches instalados."]],
  "ss32": ["Un escáner reporta una vulnerabilidad crítica en un servidor, pero el analista confirma que el parche correspondiente está instalado y el servicio no es vulnerable. ¿Qué es este hallazgo?", ["Un falso negativo", "Un verdadero positivo", "Una zero-day", "Un falso positivo"], "El escáner reportó una vulnerabilidad que en realidad no existe.", ["Un falso negativo ocurre cuando una vulnerabilidad real no se reporta; aquí se reportó una que no existe.", "Un verdadero positivo significaría que la vulnerabilidad realmente existe, pero el analista confirmó que el servidor está parchado.", "Una zero-day es una vulnerabilidad que todavía no tiene parche disponible, mientras que este hallazgo se refiere a un problema ya parchado.", null]],
  "ss33": ["¿Qué debe obtenerse ANTES de que comience una prueba de penetración?", ["Una lista de todas las contraseñas de los empleados", "La aprobación del proveedor de servicios de internet de la organización", "Una autorización por escrito con un alcance acordado y reglas de enfrentamiento", "Una copia del informe de auditoría del año pasado"], "Sin una autorización por escrito y un alcance definido, las pruebas pueden ser ilegales y pueden interrumpir las operaciones.", ["Los testers nunca deben recopilar todas las contraseñas de los empleados por adelantado; eso viola la política de seguridad y no es un requisito previo.", "El ISP no autoriza las pruebas de tus sistemas; las autoriza el propietario del sistema, aunque puedes notificar a los proveedores según lo acordado.", null, "El informe de auditoría del año pasado puede servir como contexto, pero no es obligatorio y no autoriza las pruebas."]],
  "ss34": ["¿Qué factor debería influir MÁS en el orden en que se remedian las vulnerabilidades?", ["La severidad combinada con la explotabilidad y la criticidad del activo afectado", "El orden en que el escáner las encontró", "Solo el puntaje base de CVSS", "Qué tan rápido puede instalarse cada parche"], "La priorización basada en el riesgo pondera la severidad frente a la exposición real y la importancia para el negocio.", [null, "El orden de descubrimiento del escáner es arbitrario y no refleja nada sobre el riesgo.", "El puntaje base de CVSS ignora tu entorno, como la criticidad del activo y si la falla está expuesta o se explota activamente.", "La facilidad de parchado afecta el esfuerzo, pero corregir primero los problemas fáciles de bajo riesgo puede dejar abiertas exposiciones críticas."]],
  "ss35": ["¿De qué depende MÁS la correlación en un SIEM de eventos de firewalls, servidores y aplicaciones?", ["De formatos de log idénticos en todos los dispositivos", "De almacenar los logs en el mismo disco que el SIEM", "De usar el mismo fabricante para todos los dispositivos", "De la hora sincronizada en todas las fuentes de logs"], "Una hora coherente (NTP) permite ubicar los eventos en la secuencia correcta; el SIEM puede normalizar los formatos.", ["Los SIEM interpretan y normalizan distintos formatos de log, así que no se requieren formatos idénticos.", "La ubicación de almacenamiento de los logs no influye en la correlación, y guardarlos junto al SIEM no ordena los eventos.", "Un SIEM puede ingerir logs de muchos fabricantes; no se necesita un único fabricante para correlacionar.", null]],
  "ss36": ["¿Cuál es la MEJOR forma de preservar la integridad de los logs si un atacante obtiene control administrativo de un servidor?", ["Aumentar el tamaño del archivo de log local", "Reenviar los logs en tiempo real a un servidor de logs centralizado y con acceso restringido", "Comprimir los logs diariamente en el servidor", "Configurar los logs locales como de solo lectura para los usuarios estándar"], "Un atacante con derechos de administrador puede alterar los logs locales; una copia central independiente preserva el registro.", ["Un archivo de log local más grande sigue en el servidor comprometido, donde un atacante con nivel de administrador puede editarlo o eliminarlo.", null, "Los logs comprimidos siguen en el servidor y un atacante con derechos de administrador todavía puede alterarlos o borrarlos.", "Los permisos de solo lectura para usuarios estándar no detienen a un atacante que ya tiene control administrativo."]],
  "ss37": ["Para detectar actividad de red anómala, ¿qué debe establecer PRIMERO un analista?", ["Una lista de todas las firmas de malware conocidas", "Una línea base de la actividad normal", "Un informe de prueba de penetración", "Una política de vacaciones obligatorias"], "Las anomalías solo pueden identificarse comparándolas con lo que se ve como normal.", ["Las firmas de malware respaldan la detección basada en firmas, no la detección de anomalías, que necesita un modelo del comportamiento normal.", null, "Un informe de pentest enumera debilidades explotables, pero no describe el comportamiento normal de la red.", "Las vacaciones obligatorias son un control de personal para detectar fraudes, sin relación con la detección de anomalías en la red."]],
  "ss38": ["Un respondedor confirma que un ransomware está cifrando archivos en una estación de trabajo. ¿Qué debe hacer PRIMERO el respondedor?", ["Reinstalar la estación de trabajo a partir de una imagen confiable", "Ejecutar un escaneo antivirus completo y dejar que el usuario siga trabajando", "Eliminar la nota de rescate y los archivos cifrados", "Aislar la estación de trabajo de la red"], "La contención detiene la propagación; reinstalar primero también destruiría la evidencia.", ["Reinstalar de inmediato destruye la evidencia forense y no detiene la propagación a otros sistemas si el host sigue en la red.", "Dejar que el usuario siga trabajando mientras se escanea deja al ransomware libre para cifrar más archivos y recursos compartidos.", "Eliminar la nota y los archivos cifrados destruye evidencia y posiblemente datos recuperables sin detener el malware.", null]],
  "ss39": ["¿Cuál es el propósito PRINCIPAL de una reunión de lecciones aprendidas después de un incidente?", ["Mejorar los procesos y controles para que incidentes similares se eviten o se manejen mejor", "Identificar a qué empleado se debe sancionar", "Cerrar el ticket del incidente", "Calcular el rescate que se podría haber pagado"], "La revisión posterior al incidente retroalimenta mejoras hacia la preparación.", [null, "Las revisiones de lecciones aprendidas deben ser sin culpables y enfocarse en mejorar los procesos, no en elegir a alguien para sancionar.", "Cerrar el ticket es un paso administrativo; el valor de la reunión está en las mejoras que produce.", "Calcular un rescate no es el objetivo; la revisión se enfoca en mejorar la detección, la respuesta y la prevención."]],
  "ss40": ["¿Cuál de las siguientes situaciones se clasifica MEJOR como un incidente y no como un evento?", ["Un único inicio de sesión fallido de un usuario", "La finalización de un trabajo de respaldo programado", "Un inicio de sesión no autorizado confirmado en el servidor de nómina", "Un firewall que registra un intento de conexión bloqueado"], "Un incidente es un evento que realmente daña o amenaza la confidencialidad, la integridad o la disponibilidad.", ["Un único inicio de sesión fallido es un evento normal que ocurre de forma rutinaria y por sí solo no indica daño.", "Un respaldo programado exitoso es un evento operativo normal, no uno adverso.", null, "Una conexión bloqueada muestra que el firewall funciona como se espera; es un evento, no un compromiso confirmado."]],
  "ss41": ["Siguiendo el orden de volatilidad, ¿qué debe recolectarse PRIMERO de un sistema en ejecución?", ["La imagen del disco duro", "Las cintas de respaldo archivadas", "Los logs ya almacenados en un servidor syslog remoto", "El contenido de la memoria del sistema (RAM)"], "La RAM se pierde cuando se apaga el sistema, así que se recolecta antes que las fuentes menos volátiles.", ["Una imagen de disco es mucho menos volátil que la memoria y sobrevive a un apagado, así que va después de la RAM.", "Las cintas de respaldo archivadas están entre las fuentes menos volátiles y se recolectan al final.", "Los logs que ya están en un servidor syslog remoto están a salvo de los cambios locales y son mucho menos volátiles que la RAM.", null]],
  "ss42": ["¿Cuál es el propósito PRINCIPAL de la documentación de cadena de custodia?", ["Acelerar el análisis forense", "Demostrar que la evidencia estuvo controlada y sin alteraciones desde su recolección hasta su presentación", "Cifrar la evidencia para su almacenamiento", "Identificar al atacante"], "El manejo documentado respalda la integridad y la admisibilidad de la evidencia.", ["La cadena de custodia agrega pasos de documentación; su propósito es demostrar la integridad, no acelerar el análisis.", null, "Cifrar la evidencia puede protegerla, pero los registros de custodia existen para documentar quién la manipuló y cuándo.", "La cadena de custodia registra el manejo de la evidencia; identificar al atacante es el objetivo del análisis en sí."]],
  "ss43": ["Antes de analizar un disco duro incautado, ¿qué debe hacer el investigador?", ["Arrancar el disco en una estación de trabajo para revisar los archivos", "Ejecutar un antivirus en el disco original para eliminar el malware", "Crear una imagen bit a bit usando un bloqueador de escritura, verificarla por hash y analizar la copia", "Desfragmentar el disco para que el análisis sea más rápido"], "Trabajar sobre una imagen verificada protege la evidencia original contra modificaciones.", ["Arrancar el disco original escribe en él, altera las marcas de tiempo y los datos y daña su valor probatorio.", "Ejecutar un antivirus en el original puede eliminar o modificar archivos, destruyendo la evidencia.", null, "Desfragmentar reescribe la estructura del disco, destruye el slack space y los datos no asignados y altera la evidencia."]],
  "ss44": ["¿Qué actividad determina el tiempo máximo de inactividad tolerable de los procesos de negocio?", ["Análisis de impacto al negocio (BIA)", "Evaluación de vulnerabilidades", "Prueba de penetración", "Ejercicio de mesa (tabletop)"], "El BIA identifica las funciones críticas y el impacto de su pérdida a lo largo del tiempo, lo que define el MTD, el RTO y el RPO.", [null, "Una evaluación de vulnerabilidades encuentra debilidades técnicas, no cuánto tiempo pueden estar detenidos los procesos de negocio.", "Una prueba de penetración verifica si las debilidades pueden explotarse y no dice nada sobre la inactividad tolerable.", "Un ejercicio tabletop prueba un plan que ya existe; no determina los valores de MTD sobre los que se construye el plan."]],
  "ss45": ["La dirección establece que el sistema de pedidos no puede perder más de cuatro horas de transacciones. ¿Qué métrica define esto?", ["Recovery point objective (RPO)", "Recovery time objective (RTO)", "Tiempo máximo de inactividad tolerable (MTD)", "Tiempo medio entre fallas (MTBF)"], "El RPO es la pérdida máxima aceptable de datos expresada en tiempo.", [null, "El RTO es qué tan rápido debe restaurarse un sistema, una medida de inactividad y no de pérdida de datos.", "El MTD es el tiempo total que un proceso puede estar indisponible antes de que el daño sea inaceptable, no la pérdida de datos aceptable.", "El MTBF es una medida de confiabilidad del tiempo esperado entre fallas de hardware, no un objetivo de recuperación."]],
  "ss46": ["Las operaciones deben reanudarse a pocas horas de un desastre en una ubicación alternativa que ya tenga equipos y datos casi actualizados. ¿Qué opción es la MÁS apropiada?", ["Sitio tibio (warm site)", "Sitio frío (cold site)", "Sitio caliente (hot site)", "Acuerdo recíproco con una empresa asociada"], "Solo un sitio caliente está listo para asumir las operaciones en cuestión de horas.", ["Un sitio tibio tiene algunos equipos, pero normalmente requiere restaurar datos y configurar, lo que lleva días en lugar de horas.", "Un sitio frío solo ofrece espacio, energía y conectividad, y puede tardar semanas en estar operativo.", null, "Los acuerdos recíprocos son difíciles de hacer cumplir y la capacidad del socio puede no estar disponible en cuestión de horas."]],
  "ss47": ["¿En qué prueba de recuperación ante desastres los miembros del equipo repasan verbalmente sus roles en un escenario sin activar ningún sistema?", ["Prueba de interrupción total", "Ejercicio de mesa (tabletop)", "Prueba en paralelo", "Prueba de failover"], "Un tabletop se basa en la discusión; los demás realmente ejecutan los sistemas de recuperación.", ["Una prueba de interrupción total realmente apaga las operaciones principales y hace failover; es la prueba más disruptiva.", null, "Una prueba en paralelo levanta los sistemas de recuperación junto a producción para procesar datos reales.", "Una prueba de failover realmente traslada las cargas de trabajo a los sistemas de respaldo en lugar de solo discutir los roles."]],
  "ss48": ["¿Qué estrategia de respaldo requiere solo el último respaldo completo y el conjunto de respaldo más reciente para realizar una restauración?", ["Completo más incremental", "Solo incremental", "Solo una instantánea (snapshot) del sistema operativo", "Completo más diferencial"], "Un diferencial contiene todos los cambios desde el último respaldo completo, así que solo se necesita el más reciente.", ["Completo más incremental necesita el respaldo completo y todos los incrementales posteriores, no solo el conjunto más reciente.", "Solo incremental no tiene una base y requeriría toda la cadena de respaldos para restaurar.", "Una instantánea del sistema operativo no incluye los datos de los usuarios y no es una estrategia de respaldo completa.", null]],
  "ss49": ["Una política exige que los datos de una laptop robada sean ilegibles. ¿Qué control cumple MEJOR este requisito?", ["Una contraseña de inicio de sesión fuerte", "Un candado de cable", "Cifrado de disco completo", "Registro remoto de logs"], "El cifrado en reposo protege la confidencialidad incluso cuando el dispositivo está en manos de otra persona.", ["Una contraseña de inicio de sesión puede evadirse retirando el disco y leyéndolo en otra máquina.", "Un candado de cable desalienta el robo, pero no sirve de nada una vez que la laptop fue robada.", null, "El registro remoto anota la actividad, pero no vuelve ilegibles para un ladrón los datos almacenados."]],
  "ss50": ["¿Cuál es la MEJOR forma de verificar que un instalador descargado no fue alterado?", ["Comparar su hash SHA-256 con el valor publicado en el sitio confiable del fabricante", "Verificar que el tamaño del archivo sea el mismo que el del fabricante", "Escanearlo con un antivirus", "Confirmar que el nombre del archivo coincide con el del fabricante"], "Un hash criptográfico cambia aunque cambie un solo bit, así que una coincidencia demuestra la integridad.", [null, "Que coincida el tamaño es una evidencia débil, porque un atacante puede alterar el contenido manteniendo el mismo tamaño.", "Un antivirus puede detectar malware conocido, pero no puede demostrar que el archivo coincide con lo que publicó el fabricante.", "Los nombres de archivo se copian trivialmente, así que un nombre coincidente no prueba nada sobre el contenido."]],
  "ss51": ["¿Por qué los protocolos seguros usan criptografía asimétrica para intercambiar una clave de sesión simétrica?", ["Las claves simétricas no pueden usarse para cifrar a través de redes", "La criptografía asimétrica es más rápida para grandes cantidades de datos", "Elimina la necesidad de certificados", "La criptografía asimétrica resuelve la distribución de claves, mientras que la simétrica es más rápida para grandes volúmenes de datos"], "El enfoque híbrido combina las fortalezas de ambas.", ["Las claves simétricas se usan de forma rutinaria para cifrar en redes; el desafío es compartirlas de forma segura, no usarlas.", "La criptografía asimétrica es mucho más lenta que la simétrica, y por eso no se usa para grandes volúmenes de datos.", "El intercambio híbrido de claves sigue dependiendo de certificados para autenticar la clave pública del servidor.", null]],
  "ss52": ["Para crear una firma digital, ¿con qué clave cifra el remitente el hash del mensaje?", ["La clave pública del remitente", "La clave privada del remitente", "La clave pública del destinatario", "Una clave simétrica compartida"], "Cualquiera puede verificarla con la clave pública del remitente, y solo el remitente pudo haberla producido.", ["La clave pública del remitente está disponible para todos, así que usarla no demostraría quién creó la firma.", null, "Cifrar con la clave pública del destinatario brinda confidencialidad al destinatario, no prueba de la identidad del remitente.", "Una clave simétrica compartida puede ser usada por ambas partes, así que no puede proporcionar no repudio."]],
  "ss53": ["¿Cuál es el propósito PRINCIPAL de agregar un salt único antes de aplicar hash a las contraseñas?", ["Hacer que el hash sea reversible para poder recuperarla", "Frustrar los ataques con rainbow tables precalculadas y ocultar contraseñas idénticas", "Cifrar la contraseña durante la transmisión", "Acortar el hash almacenado"], "Un salt único hace que cada hash sea diferente, así que las tablas precalculadas se vuelven inútiles.", ["El salt no hace que los hashes sean reversibles; el hash sigue siendo una función unidireccional.", null, "El salt se aplica al momento del almacenamiento y no protege la contraseña en tránsito; eso lo hace TLS.", "Un salt no acorta el hash; la longitud de la salida la fija el algoritmo de hash."]],
  "ss54": ["Un administrador debe gestionar dispositivos de red de forma remota. ¿Qué protocolo es el MEJOR reemplazo de Telnet?", ["FTP", "SNMPv1", "HTTP", "SSH"], "SSH cifra la sesión, incluidas las credenciales, mientras que Telnet envía todo en texto claro.", ["FTP transfiere archivos y, igual que Telnet, envía las credenciales en texto claro.", "SNMPv1 sirve para monitorear dispositivos y usa community strings en texto claro, así que no es un shell remoto seguro.", "HTTP es tráfico web sin cifrar y expone las credenciales igual que Telnet.", null]],
  "ss55": ["¿Por qué se prefieren las suites de cifrado ECDHE para TLS?", ["Proporcionan forward secrecy, de modo que las sesiones pasadas siguen protegidas si la clave privada del servidor se compromete más adelante", "Eliminan la necesidad de certificados de servidor", "No usan criptografía de clave pública", "Hacen que TLS sea compatible con SSL 2.0"], "El intercambio de claves efímero significa que las claves de sesión no pueden derivarse de la clave de largo plazo.", [null, "Las suites ECDHE siguen usando certificados de servidor para autenticar al servidor; ECDHE solo se encarga del acuerdo de claves.", "ECDHE es Diffie-Hellman de curva elíptica, que en sí mismo es criptografía de clave pública.", "SSL 2.0 es obsoleto e inseguro, y las suites ECDHE no tienen que ver con la compatibilidad con él."]],
  "ss56": ["¿Dónde debe almacenarse la clave privada de la autoridad certificadora raíz de una organización para lograr la protección más fuerte?", ["En el disco del sistema del servidor de la CA", "En un archivo protegido con contraseña en un recurso compartido", "En un módulo de seguridad de hardware (HSM) mantenido fuera de línea", "En el propio certificado"], "Los HSM generan y protegen las claves en hardware resistente a manipulaciones, y una raíz fuera de línea reduce la exposición.", ["Guardar la clave en el disco del sistema de un servidor la expone al malware y a cualquiera que comprometa el servidor.", "Un archivo protegido con contraseña en un recurso compartido puede copiarse y atacarse por fuerza bruta fuera de línea.", null, "Los certificados contienen la clave pública; la clave privada nunca se incluye en el certificado."]],
  "ss57": ["¿Qué mecanismo permite a un cliente verificar el estado de revocación actual de un solo certificado casi en tiempo real?", ["Lista de revocación de certificados (CRL)", "Solicitud de firma de certificado (CSR)", "Custodia de claves (key escrow)", "Online Certificate Status Protocol (OCSP)"], "OCSP responde una consulta sobre un certificado; las CRL son listas publicadas que se actualizan periódicamente.", ["Una CRL es una lista publicada periódicamente con todos los certificados revocados, así que puede estar desactualizada y no es una consulta por certificado.", "Una CSR es lo que un solicitante envía a una CA para pedir un certificado; no tiene nada que ver con el estado de revocación.", "La custodia de claves guarda copias de las claves con un tercero de confianza para su recuperación y no informa el estado de revocación.", null]],
  "ss58": ["¿En qué capa del modelo OSI toman los routers decisiones de reenvío basadas en direcciones IP?", ["Capa 2 (enlace de datos)", "Capa 3 (red)", "Capa 4 (transporte)", "Capa 7 (aplicación)"], "El direccionamiento IP y el enrutamiento ocurren en la capa de red.", ["Los dispositivos de capa 2, como los switches, reenvían tramas usando direcciones MAC, no direcciones IP.", null, "La capa 4 se encarga del transporte de extremo a extremo con puertos TCP y UDP, no del enrutamiento entre redes.", "La capa 7 es donde operan aplicaciones como HTTP y DNS; los routers no reenvían basándose en ella."]],
  "ss59": ["Un atacante envía respuestas ARP falsificadas para que el tráfico destinado al gateway predeterminado vaya a la dirección MAC del atacante. ¿Qué contramedida es la MÁS efectiva?", ["Habilitar DNSSEC", "Aplicar SYN cookies en los servidores", "Habilitar dynamic ARP inspection en los switches", "Cambiar la contraseña del Wi-Fi"], "DAI valida los paquetes ARP contra asociaciones confiables y descarta las respuestas falsificadas.", ["DNSSEC protege las respuestas DNS contra la falsificación y no hace nada contra respuestas ARP falsificadas en la LAN.", "Las SYN cookies protegen a los servidores contra los SYN floods, no contra el ARP spoofing.", null, "Cambiar la contraseña del Wi-Fi no impide que un atacante que ya está en la red envíe respuestas ARP falsificadas."]],
  "ss60": ["¿Qué técnica ayuda a un servidor a resistir un SYN flood sin agotar su tabla de conexiones?", ["SYN cookies", "Port mirroring", "Filtrado por MAC", "Aumentar el tiempo de concesión de DHCP"], "Las SYN cookies evitan almacenar el estado de las conexiones semiabiertas hasta que se completa el handshake.", [null, "El port mirroring copia el tráfico a un puerto de monitoreo y no reduce el estado de las conexiones semiabiertas.", "El filtrado por MAC controla qué dispositivos pueden unirse a una red y es fácil de evadir; no ayuda contra paquetes SYN falsificados.", "El tiempo de concesión de DHCP afecta la asignación de direcciones y no tiene nada que ver con las tablas de conexiones TCP."]],
  "ss61": ["¿Qué control protege MEJOR a los clientes contra el envenenamiento de caché DNS?", ["Validación DNSSEC", "Usar reservas de DHCP", "Deshabilitar ICMP", "Usar un time-to-live de DNS más corto"], "DNSSEC firma los registros DNS para que los resolvers puedan verificar su origen e integridad.", [null, "Las reservas de DHCP fijan la dirección IP de un cliente y no verifican la autenticidad de las respuestas DNS.", "Deshabilitar ICMP afecta el ping y los mensajes de error, no la integridad de los registros DNS.", "Un TTL más corto puede reducir el tiempo que un registro envenenado permanece en caché, pero no evita el envenenamiento."]],
  "ss62": ["Solo los dispositivos con parches al día y antivirus en ejecución deben poder conectarse a la red interna. ¿Qué solución cumple MEJOR esta necesidad?", ["Direccionamiento IP estático", "Un web application firewall", "Control de acceso a la red (NAC) con evaluación de postura", "Un balanceador de carga"], "NAC verifica el estado del dispositivo antes de otorgar acceso y puede poner en cuarentena a los dispositivos que no cumplen.", ["El direccionamiento estático solo fija las direcciones IP y no verifica el estado de los parches ni del antivirus.", "Un WAF protege las aplicaciones web contra ataques HTTP y no evalúa los dispositivos que se unen a la red.", null, "Un balanceador de carga distribuye el tráfico entre servidores y no evalúa el estado de los endpoints."]],
  "ss63": ["En un despliegue de 802.1X, ¿qué rol cumple el switch de red?", ["Suplicante", "Autenticador", "Servidor de autenticación", "Autoridad certificadora"], "El switch retransmite las credenciales entre el suplicante y el servidor de autenticación RADIUS.", ["El suplicante es el dispositivo cliente que solicita acceso, no el switch.", null, "El servidor de autenticación, normalmente RADIUS, valida las credenciales; el switch solo las retransmite.", "Una autoridad certificadora emite certificados que pueden usarse en EAP-TLS, pero no participa en la retransmisión del tráfico 802.1X."]],
  "ss64": ["¿Dónde debe ubicarse un servidor web de acceso público?", ["En la VLAN interna de usuarios", "En la misma subred que el servidor de base de datos", "Directamente en internet sin firewall", "En una subred filtrada (DMZ) separada de la red interna"], "La DMZ permite que personas externas lleguen al servidor y a la vez limita su camino hacia los sistemas internos.", ["Poner un servidor público en la VLAN de usuarios permite que cualquiera que lo comprometa llegue directamente a los usuarios internos.", "Ubicarlo junto a la base de datos significa que un servidor web comprometido da acceso directo a los datos más sensibles.", "Ubicarlo en internet sin filtrado expone a ataques todos los servicios del servidor.", null]],
  "ss65": ["¿Qué protocolo de IPsec proporciona confidencialidad para el payload del paquete?", ["Authentication Header (AH)", "Internet Key Exchange (IKE)", "Encapsulating Security Payload (ESP)", "Generic Routing Encapsulation (GRE)"], "ESP cifra el payload; AH solo proporciona integridad y autenticación.", ["AH autentica y protege la integridad de los paquetes, pero no cifra el payload.", "IKE negocia las asociaciones de seguridad y las claves; no cifra por sí mismo el tráfico de datos.", null, "GRE es un protocolo de túnel sin cifrado propio, y por eso a menudo se combina con IPsec."]],
  "ss66": ["¿Cuál debe ser la regla final de una lista de control de acceso de un firewall?", ["Denegar todo el tráfico que no esté explícitamente permitido", "Permitir todo el tráfico saliente", "Permitir todo el tráfico de las redes internas", "Registrar y permitir todo el tráfico"], "Una denegación implícita o explícita garantiza que se bloquee todo lo que no permitieron las reglas anteriores.", [null, "Permitir todo el tráfico saliente deja que el malware exfiltre datos y haga beaconing libremente.", "Confiar en todo el tráfico interno ignora las amenazas internas y los hosts internos comprometidos.", "Registrar y permitir todo haría inútil el resto del conjunto de reglas."]],
  "ss67": ["¿Qué dispositivo se ubica en línea (inline) y puede bloquear automáticamente el tráfico malicioso que detecta?", ["Un sistema de detección de intrusiones en un puerto SPAN", "Un network tap", "Un servidor syslog", "Un sistema de prevención de intrusiones (IPS)"], "Un IPS está en el camino del tráfico y puede descartar paquetes; un IDS solo genera alertas.", ["Un IDS en un puerto SPAN recibe solo una copia del tráfico, así que puede alertar pero no descartar paquetes en línea.", "Un network tap copia el tráfico de forma pasiva para monitoreo y no puede bloquear nada.", "Un servidor syslog recopila mensajes de log y no tiene capacidad para bloquear tráfico de red.", null]],
  "ss68": ["¿Qué dispositivo es el MÁS adecuado para bloquear intentos de inyección SQL contra una aplicación web?", ["Un router de filtrado de paquetes", "Un web application firewall", "Un switch de red con port security", "Un servidor DHCP"], "Un WAF inspecciona las solicitudes HTTP en la capa de aplicación en busca de patrones de ataque.", ["Un filtro de paquetes solo mira direcciones y puertos y no puede ver una inyección SQL dentro de las solicitudes HTTP.", null, "Port security limita qué direcciones MAC pueden usar un puerto del switch y no inspecciona el tráfico de aplicación.", "Un servidor DHCP asigna direcciones IP y no participa en el filtrado de solicitudes web."]],
  "ss69": ["¿Qué configuración inalámbrica es la MÁS apropiada para un nuevo despliegue empresarial?", ["WPA2-Personal con una frase de contraseña compartida", "WPA3-Enterprise con autenticación 802.1X", "WEP con una clave de 128 bits", "Red abierta con filtrado por MAC"], "El modo Enterprise da a cada usuario credenciales individuales y WPA3 ofrece la protección actual más fuerte.", ["WPA2-Personal usa una sola frase de contraseña compartida por todos, así que no hay responsabilidad individual y revocar a un usuario es difícil.", null, "WEP está roto y puede descifrarse en minutos sin importar la longitud de la clave.", "Una red abierta no tiene cifrado, y el filtrado por MAC se evade trivialmente con spoofing."]],
  "ss70": ["Los usuarios se conectan a un punto de acceso que transmite el SSID corporativo pero que en realidad es operado por un atacante. ¿Qué ataque es este?", ["Bluejacking", "War driving", "Jamming (interferencia)", "Evil twin"], "Un evil twin suplanta a un AP legítimo para interceptar tráfico o capturar credenciales.", ["El bluejacking envía mensajes no solicitados por Bluetooth y no implica un punto de acceso Wi-Fi falso.", "El war driving es buscar redes inalámbricas desde un vehículo, una actividad de reconocimiento y no la suplantación de un AP.", "El jamming interfiere las señales inalámbricas para denegar el servicio en lugar de atraer a los usuarios a una red falsa.", null]],
  "ss71": ["¿Qué tipo de malware se propaga por las redes por sí solo, sin acción del usuario?", ["Gusano (worm)", "Troyano", "Bomba lógica", "Virus de macro"], "Los gusanos se autorreplican explotando vulnerabilidades; los demás necesitan un disparador o una acción del usuario.", [null, "Un troyano se disfraza de software legítimo y depende de que el usuario lo ejecute; no se propaga por sí solo.", "Una bomba lógica permanece inactiva hasta que se cumple una condición de activación y no se propaga por las redes.", "Un virus de macro necesita que un usuario abra un documento infectado para propagarse."]],
  "ss72": ["Un malware modifica el kernel del sistema operativo para ocultar sus archivos y procesos a los administradores. ¿Qué es?", ["Adware", "Keylogger", "Rootkit", "Ransomware"], "Los rootkits subvierten el sistema operativo para ocultarse y mantener acceso privilegiado.", ["El adware muestra publicidad no deseada y normalmente no modifica el kernel para ocultarse.", "Un keylogger registra las pulsaciones de teclas; ocultarse modificando el kernel es característico de un rootkit.", null, "El ransomware se da a conocer cifrando datos y exigiendo un pago en lugar de ocultarse en el kernel."]],
  "ss73": ["¿Qué observación es el indicador MÁS fuerte de que un host interno forma parte de una botnet?", ["Un usuario que reporta un navegador lento", "Una actualización de Windows fallida", "Una papelera de reciclaje llena", "Conexiones salientes regulares a intervalos fijos hacia un dominio desconocido"], "El beaconing periódico hacia hosts desconocidos es típico del tráfico de comando y control.", ["Un navegador lento tiene muchas causas inofensivas, como extensiones o congestión de la red.", "Una actualización fallida es común y normalmente benigna, no una señal específica de pertenecer a una botnet.", "Una papelera de reciclaje llena es un estado normal de mantenimiento sin significado de seguridad.", null]],
  "ss74": ["¿Cuál es el control MÁS efectivo para evitar que se ejecuten programas no autorizados en kioscos públicos?", ["Antivirus basado en firmas", "Lista de aplicaciones permitidas (allow-listing)", "Un sistema de detección de intrusiones basado en host", "Capacitación de concientización para usuarios"], "El allow-listing bloquea todo lo que no esté aprobado explícitamente, incluido el malware desconocido.", ["El antivirus basado en firmas solo bloquea malware conocido y deja que se ejecuten programas desconocidos o sin firmar.", null, "Un HIDS detecta y alerta sobre actividad sospechosa, pero por defecto no impide que se ejecuten programas.", "La capacitación es de utilidad limitada en kioscos públicos usados por personas anónimas."]],
  "ss75": ["¿Qué herramienta de endpoint registra continuamente la actividad de los procesos y permite a un respondedor aislar un host de forma remota?", ["Firewall basado en host", "Software de cifrado de disco", "Endpoint detection and response (EDR)", "Servidor de gestión de parches"], "EDR proporciona telemetría de comportamiento, detección y acciones de respuesta como el aislamiento.", ["Un firewall de host filtra las conexiones de red, pero no registra la actividad detallada de los procesos para investigar.", "El cifrado de disco protege los datos en reposo y no ofrece capacidad de monitoreo ni de respuesta.", null, "Un servidor de gestión de parches despliega actualizaciones y no proporciona telemetría de comportamiento ni aislamiento de hosts."]],
  "ss76": ["Antes de desplegar un parche crítico del sistema operativo en todos los servidores de producción, ¿qué debe hacer el administrador?", ["Probar el parche en un entorno de staging que replique producción", "Desplegarlo de inmediato en todos los servidores a la vez", "Esperar a que el fabricante publique el siguiente parche", "Preguntar a los usuarios si notan problemas después de instalarlo"], "Las pruebas detectan problemas de compatibilidad antes de que causen caídas y respaldan un plan de reversión.", [null, "Desplegar en todos los servidores a la vez arriesga una caída generalizada si el parche tiene problemas de compatibilidad.", "Postergar un parche crítico hasta la siguiente versión deja abiertas vulnerabilidades conocidas.", "Depender de que los usuarios noten problemas tras el despliegue en producción no es probar, y puede causar caídas primero."]],
  "ss77": ["Se perdió un teléfono de la empresa que contiene correo sensible. ¿Qué capacidad de MDM protege MEJOR los datos?", ["Borrado remoto", "Geofencing", "Lista de aplicaciones permitidas", "Notificaciones push"], "El borrado remoto elimina los datos del dispositivo perdido.", [null, "El geofencing dispara acciones según la ubicación, pero por sí solo no elimina los datos de un teléfono perdido.", "La lista de aplicaciones permitidas controla qué apps pueden ejecutarse, lo que no protege los datos que ya están en un dispositivo perdido.", "Las notificaciones push envían mensajes al dispositivo y no ofrecen protección de datos."]],
  "ss78": ["En un programa BYOD, ¿qué función de MDM separa MEJOR los datos corporativos de los personales?", ["Borrado remoto del dispositivo completo", "Liberación del operador (carrier unlocking)", "Contenerización", "Detección de jailbreak"], "Un contenedor mantiene separadas las apps y los datos corporativos para que puedan gestionarse y borrarse sin tocar los datos personales.", ["Un borrado completo del dispositivo también elimina los datos personales, que es justamente lo que la separación en BYOD intenta evitar.", "La liberación del operador permite que un teléfono funcione en otras redes y no tiene nada que ver con la separación de datos.", null, "La detección de jailbreak verifica la integridad del dispositivo, pero no separa los datos corporativos de los personales."]],
  "ss79": ["Bajo el modelo IaaS, ¿quién es responsable de parchar el sistema operativo invitado?", ["El proveedor de nube", "El cliente de la nube", "El fabricante del hipervisor", "El proveedor de servicios de internet"], "En IaaS el proveedor asegura las capas física y de virtualización; el cliente gestiona el sistema operativo y lo que está por encima.", ["En IaaS el proveedor asegura los hosts físicos y la capa de virtualización, no el sistema operativo invitado del cliente.", null, "El fabricante del hipervisor provee el software de virtualización y no tiene acceso ni responsabilidad sobre el parchado del sistema operativo invitado.", "El ISP solo provee conectividad y no tiene ningún papel en el parchado de servidores en la nube."]],
  "ss80": ["Un bucket de almacenamiento en la nube mal configurado expuso datos de clientes. ¿Qué herramienta detecta MEJOR este tipo de malas configuraciones de forma continua?", ["Sistema de detección de intrusiones de red", "Prevención de pérdida de datos en los endpoints", "Un escáner de vulnerabilidades ejecutado una vez al año", "Cloud security posture management (CSPM)"], "CSPM verifica continuamente las configuraciones de la nube contra políticas de seguridad y benchmarks.", ["Un IDS de red vigila el tráfico en busca de ataques y no evalúa la configuración del almacenamiento en la nube.", "El DLP de endpoints monitorea los datos que salen de los dispositivos de los usuarios, no los permisos configurados en los buckets de la nube.", "Un escaneo de vulnerabilidades anual no es continuo y normalmente no verifica las configuraciones de los servicios en la nube.", null]],
  "ss81": ["Un atacante sale de una máquina virtual invitada para acceder al hipervisor. ¿Cómo se llama esto?", ["VM sprawl", "Hyperjacking mediante phishing", "VM escape", "Migración en vivo"], "El VM escape compromete el aislamiento entre los invitados y el host.", ["El VM sprawl es el crecimiento descontrolado de VM no gestionadas, no un ataque que sale de un invitado.", "El hyperjacking consiste en tomar el control del hipervisor, a menudo instalando uno malicioso; no se realiza mediante phishing ni describe la salida desde un invitado.", null, "La migración en vivo es una función legítima que mueve una VM en ejecución entre hosts."]],
  "ss82": ["Las máquinas virtuales no gestionadas se están multiplicando y muchas no tienen parches. ¿Cuál es el MEJOR control?", ["Un proceso formal de aprovisionamiento con inventario y gestión del ciclo de vida de las VM", "Aumentar la memoria del host", "Tomar snapshots con más frecuencia", "Mover todas las VM a un solo host"], "El VM sprawl se controla con la aprobación, el seguimiento y el retiro de las máquinas virtuales.", [null, "Más memoria en el host permite ejecutar todavía más VM no gestionadas y no resuelve el parchado ni el seguimiento.", "Los snapshots conservan el estado de las VM, pero aumentan el sprawl y no parchan ni inventarían las máquinas.", "Consolidar en un solo host crea un punto único de falla y no pone las VM bajo gestión."]],
  "x1": ["Un banco exige que el personal en roles de transferencias bancarias se tome dos semanas consecutivas de descanso cada año mientras otra persona realiza sus tareas. ¿Cuál es el propósito PRINCIPAL de seguridad?", ["Exponer un fraude que depende de que el empleado esté presente de forma continua", "Reducir el agotamiento y mejorar la retención del personal capacitado", "Imponer la separación de funciones entre la creación y la aprobación de transferencias", "Aplicar el mínimo privilegio quitando de forma permanente el acceso del empleado"], "Las vacaciones obligatorias obligan a que otra persona haga el trabajo, lo que tiende a revelar un fraude en curso que el empleado ausente estaba ocultando. La separación de funciones divide una tarea entre personas al mismo tiempo; es un control distinto.", [null, "El descanso es un beneficio secundario, pero el propósito de seguridad es detectar un fraude que necesita la presencia constante del empleado.", "La separación de funciones divide una tarea entre personas al mismo tiempo; las vacaciones obligatorias son un control distinto.", "El acceso se suspende, como mucho, de forma temporal; el empleado vuelve a su rol después."]],
  "x2": ["Un cliente niega haber aprobado una transacción en línea de gran monto. ¿Qué control permitiría MEJOR a la empresa demostrar que el cliente la aprobó?", ["Cifrar la transacción con una clave simétrica compartida con el cliente", "Una firma digital creada con la clave privada del cliente", "Un checksum CRC almacenado con el registro de la transacción en la base de datos", "Cifrado TLS entre el navegador del cliente y el servidor"], "Solo el cliente posee la clave privada, así que una firma válida proporciona no repudio. Una clave simétrica compartida la tienen ambas partes, así que la empresa podría haber generado el resultado por su cuenta.", ["Ambas partes tienen la clave simétrica compartida, así que la empresa podría haber generado el registro por su cuenta.", null, "Un CRC detecta cambios accidentales, pero cualquiera puede recalcularlo, así que no prueba nada sobre quién aprobó.", "TLS protege los datos en tránsito, pero no vincula después la aprobación con el cliente."]],
  "x3": ["Una empresa investigó las amenazas a su sistema de pagos y luego implementó los controles recomendados y los mantiene. Implementar y mantener los controles se describe MEJOR como:", ["Due diligence (diligencia debida)", "Separación de funciones", "Due care (debido cuidado)", "Transferencia del riesgo"], "El due care es actuar como lo haría una organización razonable y prudente, implementando y manteniendo protecciones. La due diligence es la investigación previa, no la acción continua.", ["La due diligence es la investigación y el análisis previos, no la implementación y el mantenimiento.", "La separación de funciones divide tareas entre personas; no describe la implementación de protecciones.", null, "La transferencia del riesgo traslada el impacto financiero a otra parte, como una aseguradora, en lugar de implementar controles."]],
  "x4": ["Los carteles que advierten que las instalaciones están bajo videovigilancia y que se procesará a los intrusos son PRINCIPALMENTE ¿qué tipo de control?", ["Detectivo", "Correctivo", "Compensatorio", "Disuasivo"], "Los carteles de advertencia buscan desalentar a alguien de intentar un acto no deseado, lo que los convierte en disuasivos. Las cámaras en sí son detectivas, pero el propósito del cartel es desalentar.", ["Los controles detectivos identifican los eventos cuando ocurren; las cámaras pueden ser detectivas, pero el cartel busca desalentar.", "Los controles correctivos reparan las cosas después de un incidente, algo que un cartel de advertencia no hace.", "Los controles compensatorios reemplazan a un control principal que no puede usarse; un cartel no es un sustituto.", null]],
  "x5": ["Después de detectar malware, un sistema restaura automáticamente los archivos modificados desde un respaldo confiable. ¿Qué tipo de control es esta restauración?", ["Correctivo", "Preventivo", "Disuasivo", "Directivo"], "Los controles correctivos reparan o restauran los sistemas después de que ocurrió un incidente. Los controles preventivos detienen el evento antes de que ocurra, lo que ya no es posible una vez que los archivos cambiaron.", [null, "Los controles preventivos detienen un evento antes de que ocurra; los archivos ya habían sido modificados.", "Los controles disuasivos desalientan los intentos, algo que restaurar desde un respaldo no hace.", "Los controles directivos indican a las personas qué hacer, como las políticas; no restauran sistemas."]],
  "x6": ["Los administradores de bases de datos realizan respaldos, aplican reglas de acceso y mantienen la integridad de los datos según las decisiones que toma el negocio. ¿Qué rol respecto de los datos cumplen?", ["Propietario de los datos", "Custodio de los datos", "Titular de los datos (data subject)", "Usuario de los datos"], "Los custodios llevan a cabo la protección diaria de los datos según las indicaciones del propietario. El propietario de los datos toma las decisiones sobre la clasificación y el acceso, pero no realiza las tareas técnicas.", ["El propietario decide la clasificación y el acceso, pero no realiza los respaldos ni el mantenimiento diario.", null, "El titular de los datos es la persona a la que se refieren los datos, no el personal que los mantiene.", "Los usuarios de los datos simplemente los usan según las reglas y no administran los respaldos ni el acceso."]],
  "x7": ["Unos discos duros que contenían datos sensibles se reutilizarán en un departamento de menor confianza. Deben resistir técnicas de recuperación de laboratorio pero seguir siendo utilizables. ¿Qué nivel de sanitización se necesita?", ["Clear (limpieza)", "Destroy (destrucción)", "Purge (purga)", "Formateo rápido"], "La purga protege contra la recuperación de laboratorio y deja el medio reutilizable. La limpieza (clear) solo protege contra una recuperación simple y no invasiva, y la destrucción dejaría los discos inutilizables.", ["La limpieza (clear) solo protege contra una recuperación simple y no invasiva, no contra técnicas de laboratorio.", "La destrucción deja los discos inutilizables, pero deben reutilizarse.", null, "Un formateo rápido deja la mayoría de los datos recuperables con herramientas básicas."]],
  "x8": ["Un calendario de retención indica que las facturas se conservan durante siete años. Un empleado encuentra facturas de nueve años todavía en un servidor de archivos, y no aplica ninguna retención legal. ¿Qué debe ocurrir?", ["Conservarlas indefinidamente, porque guardar más datos siempre es más seguro", "Moverlas a un archivo sin cifrar para ahorrar costos de almacenamiento", "Enviarlas por correo al gerente de finanzas para que las revise antes de eliminarlas", "Eliminarlas de forma segura según la política de retención"], "Una vez que los datos superan su período de retención y no aplica ninguna retención legal, la eliminación segura reduce la responsabilidad y la exposición. Conservarlos indefinidamente aumenta la cantidad de datos que podrían filtrarse o ser requeridos en un litigio.", ["Conservar datos más allá de su período de retención aumenta la exposición ante brechas y los costos de discovery.", "Mover datos vencidos a un archivo sin cifrar los conserva y debilita su protección.", "Enviar facturas sensibles por correo las difunde aún más en lugar de eliminarlas.", null]],
  "x9": ["Una solicitud de cambio para una actualización importante de base de datos incluye resultados de pruebas y aprobación, pero no pasos para volver a la versión anterior si la actualización falla. ¿Qué falta?", ["Un plan de reversión (backout)", "Un análisis de impacto", "Un análisis de impacto al negocio", "Un acuerdo de nivel de servicio"], "Un plan de reversión (rollback) describe cómo deshacer un cambio fallido y restaurar el servicio. El análisis de impacto evalúa de antemano los efectos del cambio, pero no describe cómo revertirlo.", [null, "El análisis de impacto predice de antemano los efectos de un cambio; no describe cómo deshacerlo.", "Un BIA prioriza los procesos de negocio para la planificación de continuidad; no forma parte de una solicitud de cambio individual.", "Un SLA establece compromisos de servicio con un proveedor o cliente, no pasos de reversión para un cambio."]],
  "x10": ["Una organización define una línea base de configuración segura para todos los servidores web. ¿Cuál es la MEJOR forma de confirmar que los servidores siguen cumpliéndola?", ["Pedir a los administradores que confirmen el cumplimiento por correo una vez al año", "Comparar regularmente las configuraciones con la línea base e investigar las desviaciones", "Hacer que el personal vuelva a leer el documento de línea base durante la capacitación anual", "Reconstruir cada servidor web desde cero todas las semanas sin importar los cambios"], "La comparación automatizada y regular contra la línea base detecta las desviaciones de configuración con evidencia. La autodeclaración por correo no es una verificación y pasa por alto los cambios que nadie notó.", ["El autorreporte por correo no es una verificación y pasa por alto cambios que nadie notó.", null, "Volver a leer el documento no verifica ninguna configuración real de los servidores.", "Las reconstrucciones semanales son disruptivas y aun así no verifican que los sistemas reconstruidos coincidan con la línea base."]],
  "x11": ["Al comparar dos sistemas biométricos, ¿qué medida única resume MEJOR la precisión general, donde un valor más bajo es mejor?", ["Tasa de falsa aceptación", "Tasa de falso rechazo", "Tasa de error de cruce (CER)", "Tiempo promedio de registro"], "La tasa de error de cruce es el punto donde FAR y FRR son iguales, así que equilibra ambos errores en un solo número comparable. La FAR por sí sola ignora con qué frecuencia se rechaza a usuarios legítimos.", ["La FAR solo mide los impostores aceptados por error e ignora a los usuarios legítimos rechazados.", "La FRR solo mide los usuarios rechazados por error e ignora a los impostores aceptados.", null, "El tiempo de registro es una medida de usabilidad, no de precisión."]],
  "x12": ["En Kerberos, ¿qué presenta un cliente al servicio de concesión de tickets para obtener un ticket de servicio para un servidor de archivos?", ["Su contraseña enviada en texto claro", "Un certificado X.509 firmado por el servidor de archivos", "Una aserción SAML de un proveedor de identidad", "Su ticket-granting ticket (TGT) y un autenticador"], "Después del inicio de sesión inicial, el cliente usa su TGT y un autenticador nuevo para solicitar tickets de servicio, así que la contraseña no se vuelve a enviar. Kerberos está diseñado para no enviar nunca la contraseña por la red en texto claro.", ["Kerberos está diseñado para no enviar nunca la contraseña por la red.", "Kerberos estándar usa tickets del KDC, no certificados firmados por el servidor de destino.", "Las aserciones SAML se usan en la federación web, no en el servicio de concesión de tickets de Kerberos.", null]],
  "x13": ["Un sitio web de impresión de fotos pide permiso para leer las fotos de un usuario almacenadas en otro servicio, sin recibir nunca la contraseña del usuario. ¿Qué protocolo está diseñado para esta autorización delegada?", ["OAuth 2.0", "RADIUS", "Kerberos", "LDAP"], "OAuth 2.0 emite tokens de acceso con alcance limitado para que un tercero pueda actuar sobre los datos de un usuario sin la contraseña. Kerberos autentica usuarios dentro de un realm y no está diseñado para delegar acceso entre servicios web.", [null, "RADIUS autentica usuarios para el acceso a la red, no el acceso de terceros a datos web.", "Kerberos autentica dentro de un realm y no está diseñado para la delegación entre servicios web.", "LDAP es un protocolo de acceso a directorios y no emite tokens de acceso delegado."]],
  "x14": ["Un inicio de sesión requiere una contraseña y luego las respuestas a dos preguntas de seguridad. ¿Por qué esto NO es autenticación multifactor?", ["Las preguntas de seguridad cuentan como algo que tienes", "Los tres son algo que sabes", "La autenticación multifactor siempre requiere biometría", "Tres pasos superan la cantidad de factores que permite MFA"], "Varios elementos de la misma categoría son autenticación de varios pasos, no multifactor; MFA necesita al menos dos categorías distintas. La biometría es una opción para un segundo factor, no un requisito.", ["Las preguntas de seguridad son algo que sabes, no algo que tienes.", null, "MFA puede usar dos categorías de factores cualesquiera que sean distintas; la biometría no es obligatoria.", "MFA establece un mínimo de dos tipos de factores, no un máximo de pasos."]],
  "x15": ["Una revisión de accesos descubre que un empleado que cambió de rol cuatro veces todavía tiene los permisos de todos sus roles anteriores. ¿Cómo se llama esto?", ["Separación de funciones", "Mínimo privilegio", "Acumulación de privilegios (privilege creep)", "Bloqueo de cuenta"], "La acumulación de privilegios es la acumulación gradual de accesos que ya no se necesitan, normalmente tras cambios de rol. El mínimo privilegio es el principio que se está violando, no el nombre del problema.", ["La separación de funciones divide tareas entre personas; esto es un acceso excesivo en manos de una sola persona.", "El mínimo privilegio es el principio que se está violando, no el nombre del problema.", null, "El bloqueo de cuenta es una respuesta a los inicios de sesión fallidos, sin relación con los permisos sobrantes."]],
  "x16": ["La cuenta de servicio de una aplicación de respaldos tiene una contraseña que nunca cambia, que conocen varios administradores y que ellos también usan para iniciar sesión de forma interactiva. ¿Cuál es la MEJOR mejora?", ["Agregar la cuenta a Domain Admins para que los trabajos de respaldo nunca fallen", "Escribir la contraseña en el runbook para que nunca se pierda", "Deshabilitar la auditoría de la cuenta para reducir el ruido en los logs", "Guardarla en la bóveda de una herramienta PAM, rotar la contraseña y denegar el inicio de sesión interactivo"], "Guardar en bóveda, rotar y restringir el uso de la cuenta de servicio elimina el conocimiento compartido y el mal uso. Agregarla a Domain Admins aumenta enormemente el daño si se roba la credencial.", ["La membresía en Domain Admins aumenta enormemente el daño si se roba esta credencial compartida.", "Escribir la contraseña en un runbook difunde todavía más un secreto estático.", "Deshabilitar la auditoría elimina la visibilidad sobre el mal uso de una cuenta riesgosa.", null]],
  "x17": ["Antes de entregar sus primeras credenciales a un nuevo empleado remoto, RR. HH. verifica un documento de identidad oficial durante una videollamada en vivo. ¿Qué paso del ciclo de vida de la identidad es este?", ["Verificación de identidad (identity proofing)", "Desaprovisionamiento", "Revisión de permisos", "Recertificación"], "La verificación de identidad confirma que una persona es quien dice ser antes de crear una cuenta. La recertificación revisa los accesos existentes más adelante en el ciclo de vida, no durante el alta.", [null, "El desaprovisionamiento quita el acceso al final del ciclo de vida, no durante el alta.", "La revisión de permisos verifica qué acceso tiene una cuenta existente, no quién es la persona.", "La recertificación confirma periódicamente que el acceso existente sigue siendo necesario, después de la incorporación."]],
  "x18": ["Un sistema permite el acceso a una aplicación solo entre las 08:00 y las 18:00 para todos los usuarios, sin importar su puesto. ¿Qué modelo de control de acceso refleja esto?", ["Control de acceso discrecional", "Control de acceso basado en reglas", "Control de acceso obligatorio", "Control de acceso basado en roles"], "Una regla global que se aplica a todos, como una franja horaria, es control de acceso basado en reglas. RBAC otorga acceso según el rol de trabajo, pero aquí la regla ignora por completo los roles.", ["En DAC, los propietarios otorgan acceso a sus recursos; aquí se aplica a todos una regla de todo el sistema.", null, "MAC usa etiquetas de sensibilidad y autorizaciones, no una franja horaria.", "RBAC otorga acceso según el rol de trabajo, pero esta regla ignora por completo los roles."]],
  "x19": ["Un usuario crea una hoja de cálculo en un recurso compartido de archivos y otorga personalmente acceso de lectura a dos colegas. ¿Qué modelo de control de acceso refleja esto?", ["Control de acceso obligatorio", "Control de acceso basado en roles", "Control de acceso discrecional", "Control de acceso basado en reglas"], "En DAC, el propietario de un objeto decide quién puede acceder a él. MAC es lo opuesto: el sistema impone etiquetas y los usuarios no pueden cambiar los permisos.", ["MAC lo impone el sistema mediante etiquetas, y los usuarios no pueden cambiar los permisos.", "RBAC asigna el acceso según el rol de trabajo, no porque el propietario elija a colegas específicos.", null, "El acceso basado en reglas aplica reglas globales definidas por los administradores, no decisiones del propietario de un objeto."]],
  "x20": ["Un activo vale $80,000. Una amenaza destruiría el 50% y se espera una vez cada cuatro años. ¿Cuáles son la SLE y la ALE?", ["SLE $40,000; ALE $160,000", "SLE $80,000; ALE $20,000", "SLE $20,000; ALE $10,000", "SLE $40,000; ALE $10,000"], "La SLE es $80,000 x 0.5 = $40,000, y con un ARO de 0.25 la ALE es $40,000 x 0.25 = $10,000. Multiplicar por 4 en lugar de 0.25 da el tentador pero incorrecto $160,000.", ["Esto multiplica la SLE por 4 en lugar de por el ARO de 0.25.", "Esto usa el valor total del activo como SLE, ignorando el factor de exposición del 50%.", "Esta SLE de $20,000 aplica mal el factor de exposición; el 50% de $80,000 es $40,000.", null]],
  "x21": ["Un riesgo tiene una ALE de $30,000. Un control que cuesta $12,000 por año reduciría la ALE a $5,000. ¿Cuál es el valor anual del control para la organización?", ["$13,000", "$25,000", "$18,000", "$7,000"], "El valor es la ALE antes menos la ALE después menos el costo anual del control: $30,000 - $5,000 - $12,000 = $13,000. $25,000 es solo la reducción del riesgo e ignora lo que cuesta el control.", [null, "$25,000 es la reducción de la ALE, pero ignora el costo anual de $12,000 del control.", "$18,000 resta el costo de la ALE original, pero ignora los $5,000 de riesgo que quedan.", "$7,000 resta la ALE restante del costo del control, lo cual no es un valor con sentido."]],
  "x22": ["Después de implementar los controles, ¿qué documento debe registrar el riesgo restante, su responsable y el tratamiento elegido?", ["Formulario de cadena de custodia", "Registro de riesgos", "Análisis de impacto al negocio", "Política de uso aceptable"], "Un registro de riesgos da seguimiento a cada riesgo, su responsable, su tratamiento y su nivel residual a lo largo del tiempo. Un BIA identifica los procesos críticos y las necesidades de recuperación, no el estado del tratamiento de cada riesgo.", ["Un formulario de cadena de custodia registra el manejo de la evidencia, no los riesgos y sus responsables.", null, "Un BIA identifica los procesos críticos y las necesidades de recuperación, no el estado del tratamiento de cada riesgo.", "Una AUP indica a los usuarios qué pueden hacer con los sistemas; no da seguimiento a los riesgos."]],
  "x23": ["Un servidor web ejecuta software con una falla conocida y sin parchar, y un grupo criminal está escaneando activamente internet en busca de ella. En términos de riesgo, la falla sin parchar es la:", ["Amenaza", "Activo", "Vulnerabilidad", "Impacto"], "Una vulnerabilidad es una debilidad que puede ser explotada. El grupo criminal que la busca es la amenaza, que es la respuesta incorrecta tentadora.", ["La amenaza es el grupo criminal que busca la falla, no la falla en sí.", "El activo es el servidor web y los datos que se protegen.", null, "El impacto es el daño que resultaría si se explotara la falla."]],
  "x24": ["¿Qué publicación del NIST ofrece orientación específica para realizar evaluaciones de riesgo?", ["SP 800-61", "SP 800-88", "SP 800-63", "SP 800-30"], "NIST SP 800-30 es la guía para realizar evaluaciones de riesgo. SP 800-61 resulta tentadora porque es una guía de seguridad muy conocida, pero trata sobre el manejo de incidentes.", ["SP 800-61 trata sobre el manejo de incidentes de seguridad informática, no sobre la evaluación de riesgos.", "SP 800-88 trata sobre la sanitización de medios.", "SP 800-63 trata sobre la identidad digital y la autenticación.", null]],
  "x25": ["La dirección quiere saber si un atacante realmente podría encadenar debilidades para llegar a la base de datos de clientes, no solo ver una lista de parches faltantes. ¿Qué debe realizarse?", ["Una prueba de penetración dentro de un alcance autorizado", "Un escaneo de vulnerabilidades sin credenciales", "Una auditoría de cumplimiento de las políticas escritas", "Una revisión de los puntajes CVSS del mes pasado"], "Una prueba de penetración explota y encadena activamente las debilidades para mostrar caminos de ataque reales. Un escaneo de vulnerabilidades solo enumera debilidades potenciales sin demostrar que puedan combinarse.", [null, "Un escaneo de vulnerabilidades enumera debilidades potenciales, pero no demuestra que puedan encadenarse para llegar a los datos.", "Una auditoría de políticas revisa documentos y cumplimiento, no si un atacante puede llegar a la base de datos.", "Revisar puntajes antiguos no aporta información nueva sobre caminos de ataque reales."]],
  "x26": ["Una empresa planea almacenar registros de clientes con un proveedor de nube. Las regulaciones que debe cumplir exigen que los datos permanezcan dentro de una región geográfica específica. ¿Qué preocupación es esta?", ["Dependencia del proveedor (vendor lock-in)", "Residencia de datos", "Elasticidad", "Multi-tenancy"], "La residencia de datos es el requisito de que los datos se almacenen y procesen en una ubicación determinada. La multi-tenancy se refiere a compartir infraestructura con otros clientes, no a dónde se ubica.", ["El vendor lock-in se refiere a la dificultad de cambiar de proveedor, no a dónde se almacenan los datos.", null, "La elasticidad es la capacidad de aumentar y reducir recursos, no un requisito de ubicación.", "La multi-tenancy es compartir infraestructura con otros clientes, no una regla geográfica."]],
  "x27": ["Una regla del SIEM para inicios de sesión fallidos genera cientos de alertas al día, casi todas de una cuenta de servicio con una contraseña vencida en un solo servidor. ¿Cuál es la MEJOR acción?", ["Deshabilitar de forma permanente la regla de inicios de sesión fallidos en toda la organización", "Subir el umbral para que solo alerten ráfagas extremadamente grandes", "Corregir las credenciales de la cuenta y ajustar la regla para esa fuente conocida", "Asignar más analistas para dar por recibida cada alerta"], "Corregir la causa raíz y excluir de forma acotada la fuente benigna conocida reduce el ruido y mantiene la detección de ataques reales. Deshabilitar la regla en todas partes dejaría al SOC ciego ante ataques de adivinación de contraseñas.", ["Deshabilitar la regla en todas partes dejaría al SOC ciego ante ataques reales de adivinación de contraseñas.", "Un umbral extremo ocultaría los ataques reales junto con el ruido.", null, "Sumar analistas gasta esfuerzo en el ruido en lugar de corregir la causa."]],
  "x28": ["Un analista junior descubre que una cuenta de administrador exportó la base de datos de RR. HH. a las 2 a.m. desde una dirección IP desconocida. ¿Qué debe hacer el analista?", ["Contactar directamente al administrador y preguntarle si fue él", "Eliminar el archivo exportado para limitar la exposición", "Esperar a que lo mencione el informe semanal", "Escalar siguiendo el procedimiento documentado, con la evidencia recopilada"], "La actividad privilegiada sospechosa debe escalarse por la ruta definida para que respondan las personas correctas. Contactar al administrador podría alertar a un insider o a un atacante que esté usando la cuenta.", ["Contactar directamente al administrador podría alertar a un insider o a un atacante que esté usando la cuenta.", "Eliminar el archivo destruye evidencia y no resuelve el posible compromiso.", "Esperar una semana deja sin respuesta un posible robo de datos.", null]],
  "x29": ["Un BIA establece el tiempo máximo de inactividad tolerable de un proceso en 24 horas. ¿Cómo debe establecerse su recovery time objective?", ["En 24 horas o menos, dejando tiempo para verificar la recuperación", "Por encima de 24 horas para que el trabajo de recuperación sea lo más completo posible", "Exactamente igual al recovery point objective del mismo proceso", "Independientemente del MTD, porque el RTO solo se aplica a los datos perdidos"], "El RTO debe caber dentro del MTD, idealmente con margen; de lo contrario, el negocio supera lo que puede tolerar. El RTO se refiere al tiempo para restaurar el servicio, mientras que el RPO se refiere a la pérdida de datos aceptable.", [null, "Un RTO mayor que el MTD significa que el negocio superaría la inactividad que puede soportar.", "El RPO mide la pérdida de datos aceptable, una magnitud distinta del tiempo de recuperación.", "El RTO se refiere al tiempo para restaurar el servicio, y debe caber dentro del MTD."]],
  "x30": ["Los respaldos completos se ejecutan el domingo por la noche y los incrementales de lunes a sábado por la noche. Un servidor falla el jueves por la tarde. ¿Qué se necesita para restaurarlo?", ["Solo el respaldo completo del domingo y el incremental del miércoles", "El respaldo completo del domingo y los incrementales del lunes, martes y miércoles", "Solo el incremental del miércoles", "Solo el respaldo completo del domingo"], "Cada incremental contiene solo los cambios desde el respaldo anterior, así que se necesitan todos los incrementales desde el completo. Usar solo el último serviría con respaldos diferenciales, no con incrementales.", ["El incremental del miércoles contiene solo los cambios del miércoles, así que se perderían los cambios del lunes y del martes.", null, "Un incremental no tiene por sí solo una base completa sobre la cual aplicarse.", "Restaurar solo el respaldo completo del domingo pierde todos los cambios hechos de lunes a miércoles."]],
  "x31": ["Un equipo de recuperación levanta los sistemas en el sitio alternativo y procesa allí transacciones reales, mientras el sitio principal sigue funcionando con normalidad. ¿Qué prueba es esta?", ["Ejercicio de mesa (tabletop)", "Prueba de interrupción total", "Prueba en paralelo", "Revisión de checklist"], "Una prueba en paralelo ejecuta el sitio de recuperación junto a producción sin interrumpirla. Una prueba de interrupción total apagaría el sitio principal, lo que aquí no ocurre.", ["Un tabletop es solo una discusión, sin sistemas activados.", "Una prueba de interrupción total apaga el sitio principal, que aquí sigue funcionando.", null, "Una revisión de checklist solo verifica los documentos del plan y no ejecuta ningún sistema."]],
  "x32": ["Un sistema de archivo histórico puede tolerar varias semanas de inactividad, y la empresa quiere el sitio alternativo de menor costo. ¿Qué opción encaja?", ["Sitio caliente (hot site)", "Sitio tibio (warm site)", "Sitio espejo (mirrored site)", "Sitio frío (cold site)"], "Un sitio frío ofrece espacio y servicios básicos pero poco equipamiento, así que es el más barato y se adapta a una inactividad tolerable larga. Un sitio tibio cuesta más porque mantiene algunos equipos listos.", ["Un sitio caliente es la opción más cara y está pensado para inactividades muy cortas.", "Un sitio tibio cuesta más de lo necesario para varias semanas de inactividad tolerable.", "Un sitio espejo funciona en tiempo real y es la opción más costosa.", null]],
  "x33": ["Los trabajos de respaldo nocturnos reportaron éxito durante un año. Durante una caída, las restauraciones fallan porque los archivos de respaldo están dañados. ¿Qué práctica lo habría detectado?", ["Restauraciones de prueba periódicas que confirmen que los datos pueden recuperarse", "Aumentar la frecuencia de los respaldos a cada hora", "Cambiar de respaldos incrementales a diferenciales", "Mover los respaldos a un almacenamiento más rápido"], "Solo restaurar los datos demuestra que un respaldo sirve; los mensajes de éxito de los trabajos no. Ejecutar respaldos con más frecuencia solo produciría más copias dañadas si el problema no se detecta.", [null, "Respaldos más frecuentes solo crearían más copias dañadas si nunca se prueban.", "Cambiar el tipo de respaldo no detecta el daño en los archivos de respaldo.", "Un almacenamiento más rápido acelera los trabajos, pero no demuestra que los datos puedan restaurarse."]],
  "x34": ["Durante una brecha de datos, ¿quién debería hablar normalmente con los medios de comunicación en nombre de la organización?", ["El analista que detectó primero la brecha", "Un vocero designado o el líder de relaciones públicas", "El administrador de sistemas que restauró los servidores", "Cualquier empleado al que contacte directamente un periodista"], "Los planes de IR designan a un vocero para que los mensajes públicos sean precisos, coherentes y revisados por el área legal. El personal técnico puede conocer los detalles, pero podría divulgar por accidente información sensible o no confirmada.", ["El analista que la detectó podría divulgar detalles no confirmados o sensibles y no es una voz autorizada.", null, "El personal técnico no es un vocero autorizado y podría revelar detalles sensibles.", "Permitir que cualquier empleado hable con periodistas lleva a declaraciones inconsistentes y posiblemente perjudiciales."]],
  "x35": ["Los investigadores quieren que la evidencia de la laptop corporativa de un empleado pueda usarse en un juicio. ¿Qué práctica respalda MEJOR su admisibilidad?", ["Hacer que el gerente del empleado explore los archivos para encontrar los relevantes", "Copiar los archivos a una unidad USB arrastrándolos y soltándolos", "Usar métodos forenses documentados y repetibles y una cadena de custodia sin interrupciones", "Ejecutar herramientas de limpieza para eliminar primero los datos irrelevantes"], "Los tribunales necesitan evidencia recolectada con métodos sólidos y un historial de manejo documentado. Explorar los archivos altera metadatos como las fechas de acceso y debilita la evidencia.", ["Explorar los archivos cambia metadatos como las fechas de acceso y socava la evidencia.", "Las copias por arrastrar y soltar cambian las marcas de tiempo y omiten los datos borrados y no asignados.", null, "Las herramientas de limpieza alteran y destruyen datos, lo que arruinaría la evidencia."]],
  "x36": ["Un examinador calcula el hash de un disco antes de crear la imagen y el de la imagen después. Los dos valores SHA-256 difieren. ¿Qué significa esto?", ["La imagen sigue siendo válida, porque los hashes siempre cambian al copiar", "El disco debe estar cifrado, así que la comparación de hashes no es relevante", "La herramienta de hash debería haberse configurado en MD5 para imágenes de disco", "La imagen no es una copia exacta y no puede usarse con confianza como evidencia"], "Que los hashes coincidan demuestra una copia bit a bit; cualquier diferencia significa que los datos difieren. Los hashes no cambian solo porque los datos se copiaron, y por eso se usan para verificar.", ["Los hashes no cambian cuando los datos se copian de forma exacta; por eso se usan para verificar.", "Los discos cifrados igual pueden hashearse y compararse bit a bit.", "MD5 es más débil que SHA-256 y no haría aceptable una discrepancia.", null]],
  "x37": ["Dos sistemas comparten una clave secreta y deben verificar que los mensajes de la API no fueron alterados y que provienen de alguien que posee la clave. No se requieren firmas digitales. ¿Qué deben usar?", ["HMAC", "Un hash SHA-256 simple", "Codificación Base64", "AES en modo ECB"], "Un HMAC combina la clave compartida con un hash y ofrece integridad y autenticación del remitente como poseedor de la clave. Un hash simple puede recalcularlo cualquiera que altere el mensaje, así que no prueba nada sobre el remitente.", [null, "Cualquiera que altere el mensaje puede simplemente recalcular un hash simple, así que no prueba nada sobre el remitente.", "Base64 es una codificación, no seguridad; cualquiera puede decodificarlo y volver a codificarlo.", "El cifrado en modo ECB brinda confidencialidad con debilidades conocidas, no una verificación de integridad comprobable."]],
  "x38": ["La clave de cifrado de disco de una laptop debe protegerse para que el disco no pueda descifrarse si se retira y se coloca en otra computadora. ¿Qué componente respalda esto?", ["Un módulo de seguridad de hardware (HSM) en el centro de datos", "Un trusted platform module (TPM)", "Una lista de revocación de certificados", "Un centro de distribución de claves (KDC)"], "Un TPM es un chip del dispositivo que almacena claves y puede vincularlas a esa máquina específica y a su estado de arranque. Un HSM protege claves para servidores y servicios, no el disco de una sola laptop.", ["Un HSM protege claves para servidores y servicios en un centro de datos, no el disco de una sola laptop.", null, "Una CRL enumera certificados revocados; no almacena claves de cifrado de disco.", "Un KDC emite tickets de Kerberos; no vincula claves de disco a una computadora."]],
  "x39": ["El administrador de un servidor necesita un certificado de una autoridad certificadora pública. ¿Qué envía el administrador a la CA?", ["La clave privada del servidor", "El certificado raíz de la propia CA", "Una solicitud de firma de certificado (CSR) que contiene la clave pública", "El hash de la contraseña de administrador del servidor"], "Una CSR contiene la clave pública y los datos de identidad para que la CA los firme, mientras la clave privada permanece en el servidor. Enviar la clave privada la comprometería.", ["Enviar la clave privada a cualquiera la compromete; debe permanecer en el servidor.", "La CA ya tiene su propio certificado raíz; el administrador no lo envía.", null, "Un hash de contraseña no tiene nada que ver con la emisión de un certificado."]],
  "x40": ["En los sistemas al estilo PGP, los usuarios avalan las claves públicas de los demás firmándolas en lugar de depender de una autoridad certificadora central. ¿Cómo se llama este modelo?", ["Confianza jerárquica", "Confianza transitiva entre dominios", "Custodia de claves (key escrow)", "Red de confianza (web of trust)"], "Una red de confianza se basa en que los usuarios firmen las claves de los demás. La confianza jerárquica es el modelo basado en CA que este enfoque reemplaza.", ["La confianza jerárquica se basa en CA, que este modelo reemplaza.", "La confianza transitiva entre dominios describe confianzas de directorio entre dominios, no la firma de claves entre usuarios.", "La custodia de claves guarda copias de las claves con un tercero para su recuperación; no es un modelo de confianza.", null]],
  "x41": ["Un equipo legal necesita cifrar y firmar digitalmente mensajes de correo individuales de extremo a extremo para que solo el destinatario previsto pueda leerlos. ¿Qué tecnología encaja?", ["S/MIME", "SFTP", "IPsec en modo transporte entre los servidores de correo", "TLS entre los servidores de correo"], "S/MIME cifra y firma el mensaje en sí, de modo que permanece protegido de extremo a extremo. TLS entre servidores de correo protege cada salto, pero deja los mensajes legibles en los servidores.", [null, "SFTP asegura transferencias de archivos, no mensajes de correo individuales.", "IPsec entre servidores protege el camino de red, pero deja los mensajes legibles en cada servidor.", "TLS entre servidores de correo protege solo cada salto; los mensajes se almacenan sin cifrar en los servidores."]],
  "x42": ["Los ingenieros de red quieren una administración de dispositivos que separe la autenticación, la autorización y el registro (accounting), y que autorice y registre cada comando. ¿Qué protocolo encaja MEJOR?", ["RADIUS", "TACACS+", "LDAP", "SNMPv2c"], "TACACS+ separa las funciones AAA y admite la autorización por comando, lo que se adapta a la administración de dispositivos. RADIUS combina la autenticación y la autorización y se usa principalmente para el acceso a la red.", ["RADIUS combina la autenticación y la autorización y no autoriza comandos individuales.", null, "LDAP es un protocolo de directorio y no ofrece autorización ni registro por comando.", "SNMPv2c monitorea dispositivos con community strings y no ofrece AAA."]],
  "x43": ["Un puerto del switch de una sala de reuniones solo debe aceptar la única unidad de videoconferencia registrada. ¿Qué función del switch es la forma más simple de lograrlo?", ["Spanning Tree Protocol", "Dynamic ARP inspection", "Port security vinculado a la dirección MAC de la unidad", "DHCP relay"], "Port security limita un puerto a direcciones MAC específicas y puede desactivarlo si se conecta otro dispositivo. Dynamic ARP inspection detiene el ARP spoofing, pero no restringe qué dispositivo se conecta.", ["STP evita los bucles de switching y no restringe qué dispositivo se conecta.", "DAI detiene el ARP spoofing, pero no limita qué dispositivo se conecta al puerto.", null, "DHCP relay reenvía las solicitudes DHCP entre subredes; no restringe dispositivos."]],
  "x44": ["Un firewall procesa las reglas de arriba hacia abajo y gana la primera coincidencia. La regla 1 permite cualquier origen hacia cualquier destino en TCP 443. La regla 2 deniega todo el tráfico desde 203.0.113.50. ¿Qué ocurre con el tráfico HTTPS desde 203.0.113.50?", ["Lo deniega la regla 2", "Lo descarta la denegación implícita", "Se registra pero no se reenvía", "Lo permite la regla 1"], "Con el procesamiento por primera coincidencia, el tráfico HTTPS coincide con la regla 1 y se permite antes de que se evalúe la regla 2. La regla de denegación tendría que ubicarse por encima de la regla amplia de permiso para tener efecto.", ["Nunca se llega a la regla 2, porque la regla 1 coincide primero con el tráfico HTTPS.", "La denegación implícita solo se aplica cuando ninguna regla coincide, y la regla 1 coincide.", "Nada en estas reglas registra y descarta el tráfico; la regla 1 lo permite.", null]],
  "x45": ["¿Qué tipo de firewall registra el estado de las conexiones para que el tráfico de retorno de una sesión saliente se permita automáticamente?", ["Firewall de inspección con estado (stateful)", "Firewall de filtrado de paquetes estático", "Web application firewall", "Bridge de capa 2"], "Un firewall stateful mantiene una tabla de conexiones activas y permite el tráfico de retorno que coincide. Un filtro de paquetes estático evalúa cada paquete por separado y necesita reglas explícitas para el tráfico de retorno.", [null, "Un filtro de paquetes estático evalúa cada paquete por separado y necesita reglas explícitas para el tráfico de retorno.", "Un WAF inspecciona el tráfico de aplicación HTTP; no se define por el seguimiento del estado de las conexiones.", "Un bridge de capa 2 reenvía tramas y no registra el estado de las conexiones."]],
  "x46": ["Los gateways de dos sucursales se conectan por internet con IPsec. Todo el paquete IP original, incluidas las direcciones internas, debe cifrarse. ¿Qué modo y protocolo deben usar?", ["Modo transporte con AH", "Modo túnel con ESP", "Modo transporte con ESP", "Modo túnel con AH"], "El modo túnel encapsula todo el paquete original, y ESP proporciona el cifrado. El modo transporte con ESP cifra solo el payload y deja expuesto el encabezado IP original, y AH nunca cifra.", ["AH nunca cifra, y el modo transporte deja expuesto el encabezado IP original.", null, "El modo transporte cifra solo el payload y deja visibles las direcciones internas.", "El modo túnel con AH autentica el paquete, pero no ofrece cifrado."]],
  "x47": ["En un centro de datos, un atacante que compromete una VM web puede llegar a todas las demás VM de la misma VLAN. ¿Qué enfoque limita MEJOR el movimiento este-oeste entre cargas de trabajo individuales?", ["Instalar un firewall perimetral más grande en el borde de internet", "Habilitar WPA3 en la red inalámbrica de la oficina", "Microsegmentación con políticas por carga de trabajo", "Fusionar VLAN para que las reglas del firewall sean más simples de gestionar"], "La microsegmentación aplica políticas entre cargas de trabajo individuales y bloquea el movimiento lateral dentro de una VLAN. Un firewall perimetral inspecciona el tráfico norte-sur y nunca ve el tráfico entre VM del mismo segmento.", ["Un firewall perimetral ve el tráfico norte-sur, no el tráfico entre VM del mismo segmento.", "La configuración de seguridad inalámbrica no tiene efecto sobre el tráfico de las VM del centro de datos.", null, "Fusionar VLAN facilita el movimiento lateral en lugar de dificultarlo."]],
  "x48": ["Una empresa con 500 empleados usa WPA2-Personal con una sola frase de contraseña compartida, y un empleado que se va todavía la conoce. ¿Cuál es la MEJOR solución a largo plazo?", ["Cambiar la frase de contraseña cada vez que alguien se va", "Ocultar la difusión del SSID", "Habilitar el filtrado por MAC en todos los puntos de acceso", "Pasar a WPA2/WPA3-Enterprise con credenciales 802.1X individuales"], "El modo Enterprise da a cada usuario sus propias credenciales, que pueden revocarse de forma individual. Cambiar la frase compartida en cada salida es disruptivo y sigue dejando un secreto compartido por cientos de personas.", ["Cambiar la frase compartida en cada salida es disruptivo y sigue compartiendo un secreto con cientos de personas.", "Ocultar el SSID se evade trivialmente y no revoca la frase de contraseña conocida.", "Las direcciones MAC se falsifican fácilmente, y el ex empleado sigue conociendo la clave.", null]],
  "x49": ["¿Qué medida protege MEJOR la señalización y el contenido multimedia de las llamadas VoIP contra la escucha en la red?", ["SIP sobre TLS para la señalización y SRTP para el contenido multimedia", "Ubicar los teléfonos en la misma VLAN que las estaciones de trabajo", "Deshabilitar QoS en los switches", "Monitorear los teléfonos con SNMPv1"], "TLS cifra la señalización SIP y SRTP cifra el flujo de voz. Compartir una VLAN con las estaciones de trabajo aumenta la exposición a la escucha en lugar de reducirla.", [null, "Compartir una VLAN con las estaciones de trabajo aumenta la exposición a la escucha y a los ataques.", "QoS afecta la calidad de las llamadas, no la confidencialidad.", "SNMPv1 envía las community strings en texto claro y no hace nada para proteger las llamadas."]],
  "x50": ["Un atacante en la misma red Wi-Fi pública intercepta y altera el tráfico entre un usuario y un servidor web. ¿Qué ataque es este?", ["SYN flood", "Ataque on-path (en la ruta)", "Ataque smurf", "Amplificación DNS"], "Un atacante on-path se ubica entre dos partes y puede leer o modificar su tráfico. Un SYN flood agota las conexiones de un servidor y no intercepta nada.", ["Un SYN flood agota la tabla de conexiones de un servidor; no intercepta tráfico.", null, "Un ataque smurf es una DoS por amplificación ICMP, no una interceptación.", "La amplificación DNS es un DDoS por reflexión, no la interceptación de la sesión de un usuario."]],
  "x51": ["¿Qué puerto TCP debe permitir un firewall para LDAP sobre TLS (LDAPS) hacia un servidor de directorio?", ["389", "3389", "636", "445"], "LDAPS usa TCP 636. El puerto 389 es LDAP estándar, que resulta tentador pero no está cifrado a menos que se actualice con StartTLS.", ["389 es LDAP estándar, que no está cifrado a menos que se actualice con StartTLS.", "3389 es Remote Desktop Protocol, no LDAPS.", null, "445 es el uso compartido de archivos SMB, no LDAPS."]],
  "x52": ["Un desarrollador plantó código que elimina los registros de nómina si alguna vez se quita su ID de empleado de la base de datos de RR. HH. ¿Qué tipo de malware es este?", ["Gusano (worm)", "Troyano", "Rootkit", "Bomba lógica"], "Una bomba lógica ejecuta su payload cuando se cumple una condición específica, como que se elimine un ID. Un troyano se disfraza de software útil, que no es lo que define a este código.", ["Un gusano se propaga por sí mismo por las redes; este código espera una condición de activación.", "Un troyano se hace pasar por software útil; el rasgo que define a este código es la activación por condición.", "Un rootkit se oculta a sí mismo y a otro malware; no se define por una condición de activación.", null]],
  "x53": ["El EDR alerta sobre PowerShell ejecutando un script cargado directamente en memoria desde un valor del registro, sin que se escriba nunca un archivo malicioso en disco. El antivirus no encontró nada. ¿Qué es esto?", ["Malware sin archivos (fileless)", "Un virus de macro", "Un virus de sector de arranque", "Adware"], "El malware fileless vive en la memoria y en herramientas legítimas como PowerShell, evitando el escaneo basado en archivos. Un virus de macro vive dentro de un archivo de documento, que aquí no existe.", [null, "Un virus de macro vive dentro de un archivo de documento, y aquí no interviene ningún archivo.", "Un virus de sector de arranque infecta el registro de arranque del disco, no un script cargado desde el registro en memoria.", "El adware muestra anuncios no deseados; no describe cómo se ejecuta este código desde la memoria."]],
  "x54": ["De repente se ve que una cuenta de usuario estándar en un servidor Linux ejecuta comandos como root, aunque no está en el archivo sudoers. ¿Qué indica esto MÁS probablemente?", ["Una rotación normal de logs", "Escalada de privilegios", "Una instalación de parche fallida", "Una mala configuración de DNS"], "Obtener root sin autorización es escalada de privilegios, a menudo mediante una falla explotada. Un parche fallido no le daría derechos de root a un usuario estándar.", ["La rotación de logs archiva los archivos de log y no da privilegios de root a los usuarios.", null, "Un parche fallido podría romper un servicio, pero no le daría root a un usuario estándar.", "La configuración de DNS no tiene nada que ver con que una cuenta local se ejecute como root."]],
  "x55": ["Un gateway de correo retiene los adjuntos desconocidos y los abre en un entorno virtual aislado para observar su comportamiento antes de entregarlos. ¿Qué contramedida es esta?", ["Lista de aplicaciones permitidas", "Prevención de pérdida de datos", "Sandboxing", "Firma de código"], "El sandboxing ejecuta contenido no confiable de forma aislada para observar qué hace. DLP inspecciona los datos salientes en busca de contenido sensible en lugar de analizar los adjuntos entrantes.", ["El allow-listing permite ejecutar solo programas aprobados; no detona archivos desconocidos para observarlos.", "DLP inspecciona los datos salientes en busca de contenido sensible, no el comportamiento de los adjuntos entrantes.", null, "La firma de código verifica la identidad del editor y la integridad del archivo, no su comportamiento en ejecución."]],
  "x56": ["Antes de desplegar un nuevo servidor web Linux, ¿qué acción reduce MEJOR su superficie de ataque?", ["Habilitar todos los servicios predeterminados por si se necesitan más adelante", "Instalar un entorno de escritorio completo para facilitar la administración", "Compartir la contraseña de root con el equipo web", "Eliminar los paquetes y servicios innecesarios y aplicar un benchmark de hardening"], "El hardening elimina lo que no se necesita y aplica configuraciones seguras, reduciendo las vías de entrada. Un entorno de escritorio agrega software y servicios, lo que amplía la superficie de ataque.", ["Habilitar servicios innecesarios aumenta la superficie de ataque.", "Un entorno de escritorio agrega software y servicios, lo que amplía la superficie de ataque.", "Compartir root elimina la responsabilidad individual y aumenta la probabilidad de compromiso.", null]],
  "x57": ["Una empresa quiere ser dueña de los teléfonos de los empleados y gestionarlos por completo, pero permitiendo algo de uso personal. ¿Qué modelo de despliegue encaja?", ["Corporate-owned, personally enabled (COPE)", "Bring your own device (BYOD)", "Corporate-owned, business only (COBO)", "Teléfonos personales no gestionados con acceso al correo web"], "Los dispositivos COPE son propiedad de la empresa y los gestiona ella, pero permiten el uso personal. COBO resulta tentador porque también es propiedad de la empresa, pero no permite el uso personal.", [null, "Los dispositivos BYOD son propiedad del empleado, no de la empresa.", "Los dispositivos COBO son propiedad de la empresa, pero no permiten el uso personal.", "Los teléfonos personales no gestionados no le dan a la empresa ni propiedad ni gestión."]],
  "x58": ["Bajo el modelo SaaS, ¿cuál de estas responsabilidades sigue siendo del cliente?", ["Parchar los servidores de aplicación", "Gestionar las cuentas de usuario, el acceso y los datos que almacenan", "La seguridad física del centro de datos", "Mantener el hipervisor"], "En SaaS el proveedor opera la aplicación y la infraestructura, pero el cliente sigue controlando las identidades, el acceso y sus datos. Parchar los servidores de aplicación es tarea del proveedor en SaaS.", ["En SaaS, el proveedor parcha la aplicación y sus servidores.", null, "El proveedor es responsable de la seguridad física del centro de datos en todos los modelos de nube.", "En SaaS, el hipervisor lo gestiona el proveedor."]],
  "x59": ["Los administradores conservan decenas de snapshots antiguos de VM como respaldos informales. ¿Cuál es la PRINCIPAL preocupación de seguridad?", ["Los snapshots siempre cifran su contenido, lo que hace que la recuperación sea demasiado lenta para ser útil", "Los snapshots no pueden restaurarse una vez que la VM en ejecución fue parchada", "Pueden contener datos sensibles y reintroducir fallas sin parchar si se revierte a ellos", "Los snapshots impiden que el hipervisor bloquee los ataques de VM escape"], "Los snapshots antiguos conservan datos antiguos y vulnerabilidades antiguas, y revertir a uno deshace los parches posteriores. Los snapshots no se cifran por defecto, así que la preocupación sobre el cifrado es falsa.", ["Los snapshots no se cifran por defecto, y el cifrado no es lo que los hace riesgosos.", "Los snapshots pueden restaurarse en cualquier momento, y justamente por eso revertir puede deshacer parches.", null, "Los snapshots no cumplen ningún papel en el bloqueo de ataques de VM escape."]],
  "x60": ["Un formulario web tiene un campo de cantidad. ¿Qué enfoque de validación de entradas es el MÁS seguro?", ["Confiar en la validación con JavaScript en el navegador", "Bloquear una lista de caracteres peligrosos conocidos, como las comillas", "Aceptar cualquier entrada y registrarla para revisarla después", "Permitir solo el tipo y rango esperados, como enteros del 1 al 100"], "La lista de permitidos (allowlisting) acepta solo entradas conocidas como válidas, lo cual es más fuerte que intentar enumerar todas las entradas maliciosas. Bloquear caracteres con una lista de denegados resulta tentador, pero a menudo se evade con codificaciones o caracteres que la lista no contempló.", ["Las verificaciones del lado del cliente se evaden fácilmente enviando solicitudes directamente al servidor.", "Las listas de denegados pasan por alto codificaciones y caracteres que nadie pensó en bloquear.", "Aceptar cualquier entrada deja la aplicación expuesta a inyecciones y fallas de lógica.", null]],
});
